window.YC_MORE_QBANKS=window.YC_MORE_QBANKS||[];window.YC_MORE_QBANKS.push([{"module":"yiliao","prompt":"人体全身的骨共多少块？","options":["206","208","204","210"],"answer":0,"explanation":"成人全身骨共206块（含6块听小骨）。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1001","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"人体最长的骨是？","options":["股骨","胫骨","肱骨","腓骨"],"answer":0,"explanation":"股骨是人体最长的长骨，约占身高的27%。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1002","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脊柱成人由多少块椎骨组成？","options":["32块","24块","26块","33块"],"answer":2,"explanation":"成人脊柱由24块椎骨、1块骶骨、1块尾骨共26块组成；幼儿骶尾未融合时为33块。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1003","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"颈椎的特征性结构是？","options":["横突孔","肋凹","齿突隆起","耳状面"],"answer":0,"explanation":"颈椎横突有横突孔，内有椎动、静脉通过，是颈椎的特征。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1004","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"椎间盘由哪两部分构成？","options":["椎体和椎弓","前纵韧带和后纵韧带","纤维环和髓核","黄韧带和棘上韧带"],"answer":2,"explanation":"椎间盘中央为髓核，周围为纤维环，连接相邻椎体。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1005","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"髓核突出的方向是？","options":["向上方","向前方","向侧方","向后外方"],"answer":3,"explanation":"纤维环后外侧薄弱，髓核多向后外方突出，压迫神经根。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1006","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胸廓参与呼吸的主要肌是？","options":["斜方肌","胸锁乳突肌","膈和肋间肌","前锯肌"],"answer":2,"explanation":"平静呼吸时膈和肋间外肌是主要呼吸肌。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1007","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"膈的主动脉裂孔位置约平？","options":["第10胸椎","第8胸椎","第12胸椎","第6颈椎"],"answer":2,"explanation":"膈有三个裂孔：主动脉裂孔平第12胸椎，食管裂孔平第10胸椎，腔静脉孔平第8胸椎。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1008","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肩关节的结构特点是？","options":["肱骨头大、关节盂浅，灵活性大","关节囊厚而坚韧","有关节盘","稳定性大于灵活性"],"answer":0,"explanation":"肩关节盂浅头大、囊松弛，是全身最灵活的关节，但稳定性差易脱位。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1009","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肘关节不包括？","options":["桡腕关节","肱尺关节","肱桡关节","桡尺近侧关节"],"answer":0,"explanation":"肘关节由肱尺、肱桡、桡尺近侧三组关节构成；桡腕关节属腕部。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1010","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"髋关节与肩关节相比，其特点是？","options":["稳定性大、灵活性小","灵活性大、稳定性小","均有关节盘","均无韧带"],"answer":0,"explanation":"髋关节头深盂深、韧带强大，稳定性大而灵活性小于肩关节。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1011","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"膝关节内的重要结构是？","options":["三角韧带","关节盂唇","喙肩韧带","半月板和交叉韧带"],"answer":3,"explanation":"膝关节内有内、外侧半月板和前、后交叉韧带。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1012","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"前交叉韧带断裂时胫骨出现？","options":["向内移位","向后移位","向外移位","向前移位"],"answer":3,"explanation":"前交叉韧带防止胫骨前移，断裂后抽屉试验胫骨前移阳性。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1013","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"足弓的功能主要是？","options":["产生红细胞","分泌滑液","缓冲震荡和保护血管神经","传导痛觉"],"answer":2,"explanation":"足弓弹性结构可缓冲行走震荡，保护足底血管神经。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1014","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"颅底内面由前向后的颅窝顺序是？","options":["颅前窝、颅中窝、颅后窝","颅后窝、颅中窝、颅前窝","颅中窝、颅前窝、颅后窝","颅前窝、颅后窝、颅中窝"],"answer":0,"explanation":"颅底内面从前向后为颅前、中、后三个颅窝，位置逐渐降低。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1015","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脑颅骨共几块？","options":["8块","6块","12块","14块"],"answer":0,"explanation":"脑颅骨8块（额、筛、蝶、枕各1，颞、顶各2）；面颅骨15块。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1016","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"乳突属于哪块骨的结构？","options":["枕骨","颞骨","顶骨","蝶骨"],"answer":1,"explanation":"乳突是颞骨后下方的骨性突起，胸锁乳突肌附着处。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1017","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"翼点位于？","options":["枕骨","眶下","颞窝","鼻中隔"],"answer":2,"explanation":"翼点是额、顶、颞、蝶四骨汇合处的H形缝，骨质薄弱，内面有脑膜中动脉前支。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1018","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"上颌窦的开口位于？","options":["鼻泪管","上鼻道","下鼻道","中鼻道"],"answer":3,"explanation":"上颌窦开口于中鼻道，位置高引流不畅，易发炎。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1019","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"计数肋骨的重要体表标志是？","options":["锁骨","胸骨下角","剑突","胸骨角"],"answer":3,"explanation":"胸骨角平第2肋，是计数肋和肋间隙的标志。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1020","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肱骨外科颈骨折易损伤？","options":["正中神经","桡神经","腋神经","尺神经"],"answer":2,"explanation":"腋神经绕肱骨外科颈走行，骨折易损伤致三角肌瘫痪。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1021","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肱骨中段骨折易损伤？","options":["胸背神经","腋神经","肌皮神经","桡神经"],"answer":3,"explanation":"桡神经沿桡神经沟绕肱骨中段走行，骨折易损伤致垂腕。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1022","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"腓骨颈骨折易损伤？","options":["闭孔神经","胫神经","股神经","腓总神经"],"answer":3,"explanation":"腓总神经绕腓骨颈走行，位置表浅易损伤致足下垂。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1023","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"关节的基本结构不包括？","options":["关节面","关节唇","关节囊","关节腔"],"answer":1,"explanation":"关节基本结构为关节面、囊、腔；关节唇属辅助结构。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1024","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"滑膜关节的辅助结构不包括？","options":["韧带","关节软骨","关节盘","滑膜襞"],"answer":1,"explanation":"关节软骨属基本结构（关节面上的软骨）；韧带、盘、唇、滑膜襞为辅助结构。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1025","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脊柱的生理性弯曲有几个？","options":["4个","3个","2个","5个"],"answer":0,"explanation":"脊柱有颈、胸、腰、骶4个生理弯曲，颈腰凸向前、胸骶凸向后。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1026","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胸椎的特征性结构是？","options":["翼点","横突孔","乳突","肋凹"],"answer":3,"explanation":"胸椎椎体两侧和横突有肋凹，与肋骨相关节。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1027","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"腰椎穿刺常选择的间隙是？","options":["第3、4腰椎间","第1、2腰椎间","第5腰椎与骶椎间","第12胸椎与第1腰椎间"],"answer":0,"explanation":"成人脊髓止于第1腰椎下缘，第3、4腰椎间穿刺可避开脊髓。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1028","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肩胛骨下角平对？","options":["第9肋","第5肋","第7肋","第3肋"],"answer":2,"explanation":"肩胛骨下角平第7肋或第7肋间隙，是背部计数肋的标志。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1029","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"桡神经沟位于？","options":["肩胛骨","尺骨","桡骨","肱骨"],"answer":3,"explanation":"桡神经沟是肱骨体后面的一条斜行浅沟。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1030","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"人体最大的籽骨是？","options":["距骨","豌豆骨","跟骨","髌骨"],"answer":3,"explanation":"髌骨是全身最大的籽骨，包于股四头肌腱内。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1031","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"跟骨属于？","options":["籽骨","跖骨","趾骨","跗骨"],"answer":3,"explanation":"跗骨7块：跟、距、足舟、骰及3块楔骨；跟骨最大。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1032","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"距骨上方与什么骨构成踝关节？","options":["足舟骨","跟骨","胫腓骨下端","股骨"],"answer":2,"explanation":"踝关节由胫腓骨下端与距骨滑车构成。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1033","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胸锁乳突肌的作用是？","options":["仅使头后仰","使头向同侧倾斜、面转向对侧","上提肋助吸气","外展肩关节"],"answer":1,"explanation":"单侧收缩使头向同侧倾、面转向对侧；双侧收缩使头后仰。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1034","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"股四头肌的作用是？","options":["伸膝关节","屈膝关节","外展髋关节","内收髋关节"],"answer":0,"explanation":"股四头肌是全身最大的肌，主要作用为伸膝关节。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1035","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"小腿三头肌由什么组成？","options":["股二头肌和半腱肌","胫骨前肌和趾长伸肌","腓骨长肌和短肌","腓肠肌和比目鱼肌"],"answer":3,"explanation":"小腿三头肌=腓肠肌+比目鱼肌，会合为跟腱。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1036","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"三角肌瘫痪时肩部表现是？","options":["足下垂","翼状肩","垂腕","方肩"],"answer":3,"explanation":"三角肌萎缩失去圆隆外形称方肩，常见于腋神经损伤。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1037","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"膈收缩时胸廓容积？","options":["先大后小","减小，助呼气","不变","增大，助吸气"],"answer":3,"explanation":"膈收缩穹隆下降，胸腔容积增大，是主要吸气肌。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1038","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"腹股沟管的内口是？","options":["腹股沟管浅环","腹股沟管深环","股环","海氏三角"],"answer":1,"explanation":"腹股沟管内口为深环（腹环），外口为浅环（皮下环）。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1039","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"斜方肌瘫痪时出现？","options":["垂腕","方肩","翼状肩胛","塌肩"],"answer":3,"explanation":"斜方肌上提肩胛骨，瘫痪后肩部下垂称塌肩。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1040","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"上消化道与下消化道的分界是？","options":["幽门","食管胃连接部","回盲部","十二指肠空肠曲"],"answer":3,"explanation":"临床上以十二指肠空肠曲（Treitz韧带）为上下消化道分界。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1041","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"咽峡的构成不包括？","options":["腭舌弓","腭垂（悬雍垂）","舌根","腭咽弓"],"answer":1,"explanation":"咽峡由腭垂、腭舌弓、舌根等围成，是口与咽的分界。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1042","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"牙的构造中，暴露在口腔的部分是？","options":["牙髓","牙根","牙颈","牙冠"],"answer":3,"explanation":"牙分冠、颈、根三部，冠暴露于口腔。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1043","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"乳牙共多少颗？","options":["32颗","28颗","20颗","24颗"],"answer":2,"explanation":"乳牙20颗，恒牙28~32颗（含第三磨牙）。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1044","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"腮腺导管开口于？","options":["舌下阜","上颌第2磨牙相对的颊黏膜","舌下襞","下颌第2磨牙相对处"],"answer":1,"explanation":"腮腺导管开口于上颌第2磨牙相对的颊黏膜处。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1045","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"下颌下腺开口于？","options":["舌下襞","舌下阜","中鼻道","颊黏膜"],"answer":1,"explanation":"下颌下腺和舌下腺大管开口于舌下阜。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1046","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"食管的三处生理性狭窄不包括？","options":["与左主支气管交叉处","咽与食管移行处","食管胃连接处","穿膈肌食管裂孔处"],"answer":2,"explanation":"食管三狭窄：起始部、与左主支气管交叉处、穿膈处；食管胃连接处不属生理狭窄。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1047","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"食管第三个狭窄距中切牙约？","options":["55cm","25cm","15cm","40cm"],"answer":3,"explanation":"食管全长约25cm，三狭窄距中切牙约15、25、40cm。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1048","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胃的分部不包括？","options":["贲门部","胃底","胃体","胃小弯"],"answer":2,"explanation":"胃分贲门部、胃底、胃体、幽门部四部；胃小弯是边缘不是分部。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1049","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胃溃疡和十二指肠溃疡的好发部位分别是？","options":["幽门部胃小弯、十二指肠球部","胃底、降部","贲门部、水平部","胃大弯、升部"],"answer":0,"explanation":"胃溃疡好发幽门部胃小弯，十二指肠溃疡好发球部（前壁）。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1050","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"十二指肠大乳头位于？","options":["球部","降部","水平部","升部"],"answer":1,"explanation":"胆总管和胰管共同开口于十二指肠降部的十二指肠大乳头。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1051","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"十二指肠溃疡好发部位是？","options":["降部","球部","水平部","升部"],"answer":1,"explanation":"十二指肠球部（上部）是溃疡最好发部位。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1052","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"小肠中最长的一段是？","options":["回肠","空肠","十二指肠","盲肠"],"answer":1,"explanation":"空肠与回肠合称系膜小肠，空肠占近侧2/5、回肠占远侧3/5，回肠更长。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1053","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"小肠内环状皱襞最发达的部位是？","options":["十二指肠球部","回肠末端","十二指肠和空肠上段","空肠下段"],"answer":2,"explanation":"环状皱襞在十二指肠末段和空肠上段最发达，利于吸收。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1054","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"大肠的特征性结构不包括？","options":["绒毛","结肠带","结肠袋","肠脂垂"],"answer":0,"explanation":"结肠带、结肠袋、肠脂垂是大肠三大特征；绒毛是小肠结构。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1055","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"阑尾根部的体表投影是？","options":["McBurney点","Murphy点","Koch点","Lanz点"],"answer":0,"explanation":"阑尾根投影于脐与右髂前上棘连线中外1/3交界处（麦氏点）。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1056","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"阑尾手术寻找阑尾的可靠标志是？","options":["结肠袋","结肠带","肠脂垂","回盲瓣"],"answer":1,"explanation":"三条结肠带汇合于阑尾根部，是术中寻找阑尾的标志。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1057","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肝的位置大部分位于？","options":["左季肋区","右季肋区和腹上区","右腰区","脐区"],"answer":1,"explanation":"肝大部分位于右季肋区和腹上区，小部分位于左季肋区。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1058","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肝门的结构不包括？","options":["肝管","肝门静脉","肝固有动脉","肝静脉"],"answer":3,"explanation":"肝门有肝门静脉、肝固有动脉、肝管等出入；肝静脉自肝后缘出肝注入下腔静脉。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1059","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胆囊位于？","options":["肝左叶","肝右叶下面的胆囊窝内","十二指肠降部","胃小弯"],"answer":1,"explanation":"胆囊位于肝右叶脏面的胆囊窝内。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1060","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胆囊底的体表投影是？","options":["左锁骨中线与肋弓交点","右锁骨中线与右肋弓交点附近","脐与右髂前上棘连线中点","剑突下"],"answer":1,"explanation":"胆囊底投影于右锁骨中线（或右腹直肌外缘）与右肋弓交点处，胆囊炎压痛点。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1061","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胆总管由什么汇合而成？","options":["胆囊管与胰管","左右肝管","肝总管与胰管","肝总管与胆囊管"],"answer":3,"explanation":"左、右肝管汇成肝总管，肝总管与胆囊管汇成胆总管。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1062","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胆总管与胰管共同开口于？","options":["十二指肠球部","十二指肠大乳头","十二指肠空肠曲","幽门"],"answer":1,"explanation":"两者汇合成肝胰壶腹，开口于十二指肠降部大乳头。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1063","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胰的位置横过？","options":["骶岬前方","第3、4腰椎前方","第12胸椎前方","第1、2腰椎前方"],"answer":3,"explanation":"胰横位于腹后壁，平第1、2腰椎，横过脊柱前方。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1064","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"腹膜外位器官是？","options":["肝","胃","空肠","肾"],"answer":3,"explanation":"肾、输尿管、肾上腺、胰等为腹膜外位（后位）器官。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1065","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"腹膜内位器官是？","options":["胰","肾","空肠","膀胱"],"answer":2,"explanation":"空回肠、胃、阑尾等表面几乎全被腹膜覆盖，为内位器官。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1066","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"小网膜的组成是？","options":["肝胃韧带和肝十二指肠韧带","胃结肠韧带","膈结肠韧带","镰状韧带"],"answer":0,"explanation":"小网膜=肝胃韧带+肝十二指肠韧带（内含胆总管、肝固有动脉、门静脉）。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1067","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"直肠的两个弯曲方向是？","options":["骶曲凸向前、会阴曲凸向后","均凸向后","均凸向前","骶曲凸向后、会阴曲凸向前"],"answer":3,"explanation":"直肠骶曲凸向后（贴骶骨），会阴曲凸向前。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1068","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肛管的齿状线由什么构成？","options":["肛门外括约肌","白线","肛柱下端与肛瓣边缘连线","痔环"],"answer":2,"explanation":"齿状线是肛柱下端与肛瓣边缘的锯齿状连线，是黏膜与皮肤分界。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1069","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"齿状线上下结构的差异不包括？","options":["淋巴引流不同","动脉供应来源不同","静脉回流方向不同","神经支配均为躯体神经"],"answer":3,"explanation":"齿状线以上为内脏神经（无痛觉），以下为躯体神经（痛觉敏感）；其余均不同。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1070","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肝门静脉的属支不包括？","options":["肠系膜上静脉","肝静脉","脾静脉","胃左静脉"],"answer":1,"explanation":"肝静脉注入下腔静脉，不属门静脉属支。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1071","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肝门静脉高压时侧支循环不经过？","options":["食管静脉丛","下腔静脉-肾静脉吻合","直肠静脉丛","脐周静脉网"],"answer":1,"explanation":"门脉高压侧支循环：食管胃底静脉丛、直肠静脉丛、脐周静脉网、腹膜后静脉丛；不经肾静脉。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1072","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"乳糜池位于？","options":["第1腰椎前方","第12胸椎前方","第2骶椎前方","第5腰椎前方"],"answer":0,"explanation":"乳糜池是胸导管起始部的膨大，位于第1腰椎（膈肌主动脉裂孔）前方。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1073","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"咽的分部不包括？","options":["口咽","鼻咽","咽隐窝部","喉咽"],"answer":2,"explanation":"咽分鼻咽、口咽、喉咽三部；咽隐窝是鼻咽部的结构。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1074","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"鼻咽癌的好发部位是？","options":["扁桃体窝","咽隐窝","梨状隐窝","蝶筛隐窝"],"answer":1,"explanation":"咽隐窝是鼻咽癌好发部位，位于鼻咽侧壁。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1075","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"上呼吸道包括？","options":["鼻、咽、喉","鼻、咽、气管","喉、气管、支气管","鼻、喉、支气管"],"answer":0,"explanation":"上呼吸道为鼻、咽、喉；气管及以下为下呼吸道。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1076","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"鼻旁窦不包括？","options":["蝶窦","筛窦","上颌窦","乳突窦"],"answer":0,"explanation":"鼻旁窦4对：额、筛、蝶、上颌窦；乳突窦属中耳。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1077","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"开口于上鼻道的鼻旁窦是？","options":["额窦","上颌窦","筛窦后群","筛窦前群"],"answer":2,"explanation":"上鼻道引流筛窦后群；中鼻道引流上颌窦、额窦、筛窦前中群。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1078","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"鼻出血的好发部位是？","options":["中鼻道","鼻中隔后部","下鼻道","鼻中隔前下部（Little区）"],"answer":3,"explanation":"鼻中隔前下部血管丰富表浅，称易出血区。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1079","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"喉软骨中不成对的是？","options":["只有甲状软骨","杓状软骨","只有环状软骨","甲状软骨、环状软骨、会厌软骨"],"answer":3,"explanation":"喉软骨3块不成对（甲状、环状、会厌），成对1块（杓状）。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1080","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"喉腔中最狭窄的部位是？","options":["前庭裂","声门裂","喉口","声门下腔"],"answer":1,"explanation":"声门裂是两侧声襞之间的裂隙，为喉腔最窄处。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1081","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"环甲膜穿刺的定位依据是？","options":["甲状软骨与环状软骨之间","环状软骨与气管之间","舌骨与甲状软骨之间","第2、3气管软骨之间"],"answer":0,"explanation":"环甲膜位于甲状软骨下缘与环状软骨上缘之间，是紧急通气的穿刺部位。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1082","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"婴幼儿喉腔炎症易致喉梗阻的原因是？","options":["喉腔狭窄固定","声门裂宽大","软骨已钙化","声门下腔黏膜疏松、组织软弱"],"answer":3,"explanation":"婴幼儿声门下腔黏膜下组织疏松，炎症时易肿胀致喉梗阻。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1083","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"气管软骨环的数目约为？","options":["10个","6~8个","20~24个","14~16个"],"answer":3,"explanation":"气管由14~16个C形软骨环构成，缺口向后。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1084","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"右主支气管的特点是？","options":["粗、短、直","细、长、斜","与左主支气管相同","走行水平"],"answer":0,"explanation":"右主支气管粗短陡直，气管异物多坠入右主支气管。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1085","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肺尖的位置超出？","options":["锁骨内侧1/3上方2~3cm","锁骨外侧1/3上方","胸廓上口以下","第1肋以下"],"answer":0,"explanation":"肺尖高出锁骨内侧1/3上方2~3cm。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1086","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"左肺的分叶是？","options":["2叶（上、下）","3叶（上、中、下）","4叶","1叶"],"answer":0,"explanation":"左肺2叶（有心切迹），右肺3叶。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1087","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肺门的结构不包括？","options":["主支气管","肺动脉","肺静脉","肺韧带"],"answer":3,"explanation":"肺门有主支气管、肺动静脉、支气管动静脉、淋巴管神经；肺韧带是胸膜结构。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1088","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肋膈隐窝（肋膈窦）的临床意义是？","options":["气体常积聚处","胸腔积液常积聚处","心包积液处","肺气肿好发处"],"answer":1,"explanation":"肋膈隐窝是胸膜腔最低处，积液常积聚，是穿刺抽液部位。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1089","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胸膜腔负压的生理意义不包括？","options":["促进静脉血回流","维持肺的扩张状态","促进淋巴回流","使肺泡壁变厚"],"answer":1,"explanation":"胸内负压维持肺扩张、促进静脉淋巴回流；不使肺泡壁变厚。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1090","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肺泡隔内的吞噬细胞是？","options":[" Clara细胞","杯状细胞","尘细胞","嗜银细胞"],"answer":2,"explanation":"肺泡隔内的巨噬细胞吞噬尘粒后称尘细胞。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1091","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"气血屏障的组成不包括？","options":["胸膜脏层","肺泡上皮细胞","基膜","肺泡壁毛细血管内皮细胞"],"answer":3,"explanation":"气血屏障=肺泡上皮+基膜+毛细血管内皮（含融合基膜），不含胸膜。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1092","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"呼吸道的屏障结构不包括？","options":["黏液毯","鼻毛","纤毛","肺泡Ⅰ型上皮细胞"],"answer":3,"explanation":"Ⅰ型细胞主要行气体交换；鼻毛、纤毛、黏液、咳嗽反射属屏障防御。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1093","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"气管切开常选择的部位是？","options":["第1~2气管软骨环处","第3~5气管软骨环处","第6~8气管软骨环处","环甲膜处"],"answer":1,"explanation":"气管切开选颈段第3~5气管软骨环。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1094","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胸膜腔穿刺抽液常选？","options":["锁骨中线第2肋间抽液","肩胛线第7~8肋间（腋后线）","胸骨旁第4肋间","腋前线第5肋间"],"answer":1,"explanation":"胸腔积液穿刺常选肩胛线或腋后线第7~8肋间；气胸穿刺在锁骨中线第2肋间。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1095","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"气胸穿刺排气常选？","options":["胸骨左缘第4肋间","肩胛线第7~8肋间","腋中线第8肋间","锁骨中线第2肋间"],"answer":3,"explanation":"胸腔积气上浮，常在锁骨中线第2肋间穿刺。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1096","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肺下界的体表投影在锁骨中线处平？","options":["第8肋","第6肋","第4肋","第10肋"],"answer":1,"explanation":"肺下界：锁骨中线平第6肋、腋中线平第8肋、肩胛线平第10肋；胸膜下界比肺下界低2肋。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1097","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胸膜下界在腋中线处平？","options":["第12肋","第6肋","第10肋","第8肋"],"answer":3,"explanation":"胸膜下界比肺下界约低2个肋：锁骨中线第8肋、腋中线第10肋、肩胛线第12肋。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1098","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肺的有效气体交换面积约为？","options":["70~100m²","10~20m²","150~200m²","5~10m²"],"answer":0,"explanation":"成人肺泡约3~4亿个，总交换面积约70~100m²。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1099","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"支气管树中气体交换开始于？","options":["呼吸性细支气管","终末细支气管","段支气管","小支气管"],"answer":0,"explanation":"终末细支气管以上仅通气；呼吸性细支气管开始有气体交换功能。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1100","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肺的传导部（导气部）止于？","options":["呼吸性细支气管","终末细支气管","肺泡管","肺泡囊"],"answer":1,"explanation":"导气部从支气管到终末细支气管；呼吸性细支气管起为呼吸部。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1101","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"纵隔的分区常以什么为界？","options":["主动脉弓平面","气管分叉平面","胸骨角与第4胸椎下缘平面","肺门平面"],"answer":2,"explanation":"纵隔以胸骨角平面（平第4胸椎下缘）分上、下纵隔。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1102","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"心位于纵隔的？","options":["中纵隔","上纵隔","前纵隔","后纵隔"],"answer":0,"explanation":"心包、心位于中纵隔；胸腺位于前上纵隔。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1103","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肺循环的特点是？","options":["与体循环压力相同","路径长、压力高","路径短、压力低","只供应肺组织营养"],"answer":2,"explanation":"肺循环路径短、阻力低、压力低，为低压系统。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1104","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"呼吸系统的防御功能不包括？","options":["分泌IgA","咳嗽反射","纤毛运动","产生胃酸"],"answer":3,"explanation":"胃酸属消化系统；呼吸道防御有咳嗽反射、纤毛、黏液、分泌型IgA等。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1105","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾的位置约平？","options":["第9~11胸椎","第1~3腰椎","第11胸椎至第2腰椎","第3~5腰椎"],"answer":2,"explanation":"肾随呼吸上下移动，约平第11胸椎至第2~3腰椎，右肾略低。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1106","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"右肾略低于左肾的原因是？","options":["受肝的影响","受脾的影响","受胃的影响","受胰的影响"],"answer":0,"explanation":"肝位于右肾上方，将右肾推低约半个椎体。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1107","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾的结构单位是？","options":["肾盂","肾小盏","肾单位","集合管"],"answer":2,"explanation":"肾单位是肾结构与功能的基本单位，每侧约100万个。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1108","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"每侧肾的肾单位约有多少个？","options":["10万个","100万个","500万个","1000万个"],"answer":1,"explanation":"每侧肾约100万（100~150万）个肾单位。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1109","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾单位的组成是？","options":["肾小体和肾小管","肾小球和肾小囊","肾小管和集合管","肾小盏和肾盂"],"answer":0,"explanation":"肾单位=肾小体（小球+小囊）+肾小管。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1110","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾小体的组成是？","options":["血管球和肾小囊","肾小球和肾小管","肾小管和集合管","近曲小管和远曲小管"],"answer":0,"explanation":"肾小体由血管球（毛细血管球）和肾小囊构成。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1111","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"滤过膜的组成不包括？","options":["肾小管上皮","有孔内皮","基膜","足细胞裂孔膜"],"answer":0,"explanation":"滤过膜=毛细血管有孔内皮+基膜+肾小囊脏层足细胞裂孔膜；不含肾小管上皮。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1112","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾小管的重吸收主要发生在？","options":["远曲小管","近曲小管","髓袢","集合管"],"answer":1,"explanation":"近曲小管重吸收原尿中约65%~70%的水和绝大部分营养物质。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1113","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"原尿中绝大部分营养物质重吸收的部位是？","options":["集合管","髓袢细段","远端小管","近端小管"],"answer":3,"explanation":"葡萄糖、氨基酸等几乎全部在近端小管重吸收。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1114","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"尿液生成的调节不包括？","options":["抗利尿激素","大脑皮层直接重吸收原尿","醛固酮","交感神经"],"answer":1,"explanation":"ADH调节水重吸收、醛固酮保钠排钾、交感调节血流；皮层不直接重吸收。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1115","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"输尿管的三个狭窄不包括？","options":["膀胱三角区","肾盂与输尿管移行处","跨髂血管处","穿膀胱壁处"],"answer":0,"explanation":"输尿管三狭窄：起始部、跨髂血管处、壁内段；膀胱三角不是输尿管狭窄。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1116","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"输尿管结石易滞留的部位是？","options":["三个生理性狭窄处","输尿管中段","肾盂内","膀胱内"],"answer":0,"explanation":"结石易在狭窄处嵌顿，引起绞痛。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1117","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"膀胱三角位于？","options":["膀胱体前壁","膀胱尖","膀胱底内面","尿道内口周围"],"answer":2,"explanation":"膀胱三角=两输尿管口与尿道内口之间的三角形区域，黏膜平滑无皱襞。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1118","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"膀胱三角的特点是？","options":["黏膜多皱襞","黏膜平滑无皱襞","有大量腺体","壁最薄易穿孔"],"answer":1,"explanation":"三角区黏膜平滑无皱襞，是肿瘤和结核好发部位。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1119","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"膀胱充盈时，成人正常容量约？","options":["300~500ml","100~200ml","1000ml以上","50~100ml"],"answer":0,"explanation":"成人膀胱正常充盈容量约300~500ml。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1120","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"女性尿道的特点是？","options":["与男性相同","细长弯曲","短、直、宽，易感染","开口于阴道前庭后部"],"answer":2,"explanation":"女性尿道长约3~5cm，短直宽，易发生逆行尿路感染。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1121","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"男性尿道最狭窄处是？","options":["尿道外口","尿道内口","膜部","前列腺部"],"answer":0,"explanation":"男性尿道三狭窄：内口、膜部、外口；最窄为外口，膜部最短。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1122","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"男性尿道的分部不包括？","options":["尿道球腺部","前列腺部","膜部","海绵体部"],"answer":0,"explanation":"男性尿道分前列腺部、膜部、海绵体部三部；无球腺部。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1123","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"男性尿道最短的部位是？","options":["海绵体部","前列腺部","膜部","舟状窝"],"answer":2,"explanation":"膜部长约1.2cm，是三部中最短者。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1124","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾的被膜由内向外依次是？","options":["肾筋膜、脂肪囊、纤维囊","纤维囊、脂肪囊、肾筋膜","脂肪囊、纤维囊、肾筋膜","纤维囊、肾筋膜、脂肪囊"],"answer":1,"explanation":"肾被膜三层由内向外：纤维囊、脂肪囊（肾周脂肪）、肾筋膜。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1125","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾蒂主要结构的排列从前向后是？","options":["肾静脉、肾动脉、肾盂","肾动脉、肾静脉、肾盂","肾盂、肾动脉、肾静脉","肾动脉、肾盂、肾静脉"],"answer":0,"explanation":"肾蒂由前向后：静脉、动脉、肾盂；由上向下：动脉、静脉、肾盂。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1126","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾的固定因素不包括？","options":["邻近器官","肾筋膜","脂肪囊","肾小球的滤过压"],"answer":3,"explanation":"肾靠被膜、血管、腹压及邻近器官固定；滤过压与位置无关。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1127","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾盂结石排出时最易嵌顿于？","options":["肾盏","输尿管三个狭窄处","膀胱三角","尿道海绵体部"],"answer":1,"explanation":"狭窄处管腔小，结石易嵌顿。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1128","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾小球滤过率正常成人约为？","options":["500ml/min","50ml/min","300ml/min","125ml/min"],"answer":3,"explanation":"正常成人GFR约125ml/min（100~150ml/min）。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1129","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"正常成人24小时尿量约？","options":["200~400ml","500~800ml","3000~4000ml","1000~2000ml"],"answer":3,"explanation":"24h尿量1000~2000ml；<400ml为少尿，>2500ml为多尿。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1130","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"少尿是指24小时尿量少于？","options":["100ml","400ml","500ml","1000ml"],"answer":1,"explanation":"24h尿量<400ml（或每小时<17ml）为少尿；<100ml为无尿。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1131","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"无尿是指24小时尿量少于？","options":["100ml","400ml","50ml","200ml"],"answer":0,"explanation":"24h尿量<100ml为无尿，提示肾功能严重受损。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1132","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"多尿是指24小时尿量超过？","options":["3000ml","1500ml","2500ml","2000ml"],"answer":2,"explanation":"24h尿量>2500ml为多尿。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1133","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"排尿反射的初级中枢位于？","options":["脑桥","延髓","骶髓","下丘脑"],"answer":2,"explanation":"排尿反射初级中枢在骶髓（第2~4骶节），高级中枢在大脑皮层。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1134","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾小球有效滤过压的组成不包括？","options":["肾小球毛细血管血压","血浆胶体渗透压的促进成分","血浆胶体渗透压","肾小囊内压"],"answer":1,"explanation":"有效滤过压=毛细血管血压−（血浆胶体渗透压+囊内压）；胶体渗透压是阻力不是动力。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1135","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"男性生殖腺是？","options":["附睾","睾丸","前列腺","精囊"],"answer":1,"explanation":"睾丸产生精子并分泌雄激素，是男性生殖腺。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1136","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"精子产生的部位是？","options":["附睾管","生精小管","输精管","前列腺"],"answer":1,"explanation":"精子在睾丸生精小管产生，经附睾成熟储存。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1137","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"男性结扎常用的部位是？","options":["输精管","附睾","射精管","尿道"],"answer":0,"explanation":"输精管结扎是男性绝育常用术式。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1138","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"前列腺的位置是？","options":["膀胱与尿生殖膈之间","精囊上方","耻骨联合前方","直肠前方"],"answer":0,"explanation":"前列腺位于膀胱颈与尿生殖膈之间，包绕尿道前列腺部。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1139","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"前列腺增生压迫的结构是？","options":["射精管","尿道膜部","尿道前列腺部","膀胱三角"],"answer":2,"explanation":"前列腺中叶增生压迫尿道前列腺部，致排尿困难。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1140","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"男性直肠指检不能触及的结构是？","options":["输精管壶腹以外的输精管","前列腺","精囊","膀胱底"],"answer":0,"explanation":"直肠指检可触及前列腺、精囊、膀胱底及输精管壶腹；不能触及输精管其他段。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1141","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"女性生殖腺是？","options":["子宫","输卵管","卵巢","阴道"],"answer":2,"explanation":"卵巢产生卵子并分泌女性激素。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1142","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"卵子受精的常见部位是？","options":["输卵管壶腹部","输卵管峡部","子宫腔","输卵管漏斗部"],"answer":0,"explanation":"受精多发生在输卵管壶腹部。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1143","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"输卵管结扎常用的部位是？","options":["输卵管峡部","壶腹部","漏斗部","子宫部"],"answer":0,"explanation":"峡部管腔窄、血管少，是结扎常用部位。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1144","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"宫外孕最常见的发生部位是？","options":["输卵管壶腹部","卵巢","腹腔","宫颈"],"answer":0,"explanation":"异位妊娠以输卵管妊娠最常见，其中壶腹部最多。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1145","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"子宫的位置是？","options":["膀胱与直肠之间","膀胱前上方","直肠后","盆腔中央偏后"],"answer":0,"explanation":"子宫位于小骨盆中央、膀胱与直肠之间，呈前倾前屈位。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1146","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"维持子宫前倾的主要韧带是？","options":["骶子宫韧带","子宫阔韧带","子宫主韧带","子宫圆韧带"],"answer":3,"explanation":"圆韧带维持前倾，骶子宫韧带维持前屈，主韧带防下垂。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1147","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"防止子宫脱垂的主要结构是？","options":["卵巢悬韧带","子宫圆韧带","子宫主韧带和盆底肌","子宫阔韧带"],"answer":2,"explanation":"主韧带（子宫颈横韧带）固定子宫颈，与盆膈共同防脱垂。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1148","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"子宫颈癌的好发部位是？","options":["宫底","子宫体","宫颈管内口","子宫颈鳞状上皮与柱状上皮交界处"],"answer":3,"explanation":"鳞柱交界处（宫颈外口）是好发部位。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1149","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"月经周期中子宫内膜功能层的变化顺序是？","options":["月经期、增生期、分泌期","增生期、分泌期、月经期","分泌期、月经期、增生期","月经期、分泌期、增生期"],"answer":1,"explanation":"月经周期（以28天计）：月经期→增生期→分泌期。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1150","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"排卵一般发生在月经周期的？","options":["下次月经前14天左右","月经第1天","月经第7天","月经第28天"],"answer":0,"explanation":"排卵日约在下次月经来潮前14天。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1151","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"排卵后形成黄体，若未受精，黄体维持约？","options":["3天","7天","28天","14天"],"answer":3,"explanation":"未受精黄体维持约14天后退化（月经黄体）。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1152","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"阴道穹最深的部位是？","options":["后部","前部","左侧部","右侧部"],"answer":0,"explanation":"后穹窿最深，与直肠子宫陷凹相邻，可穿刺。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1153","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"乳房脓肿切开引流常选？","options":["放射状切口","横切口","纵切口","弧形切口"],"answer":0,"explanation":"放射状切口减少损伤输乳管。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1154","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"会阴是指？","options":["阴道前庭","仅指外生殖器","仅指肛门区","广义为盆膈以下封闭骨盆下口的全部软组织"],"answer":3,"explanation":"广义会阴为封闭骨盆下口的全部软组织；狭义为阴道口与肛门之间的区域。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1155","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"心脏的位置位于？","options":["上纵隔","前纵隔","后纵隔","中纵隔"],"answer":3,"explanation":"心位于中纵隔，2/3偏左侧。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1156","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"心的体表投影心尖指向？","options":["左锁骨中线第5肋间内0.5~1cm","右锁骨中线第4肋间","胸骨左缘第3肋间","左腋中线第6肋"],"answer":0,"explanation":"心尖由左心室构成，投影于左锁骨中线与第5肋间交点内0.5~1cm。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1157","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"心尖的搏动点在？","options":["左侧第5肋间锁骨中线内0.5~1cm","右侧第5肋间","胸骨角平面","剑突下"],"answer":0,"explanation":"心尖搏动即左室心尖投影处。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1158","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"心脏的传导系统不包括？","options":["房室结","窦房结","迷走神经","浦肯野纤维"],"answer":2,"explanation":"传导系统由特殊心肌细胞构成；迷走神经是外来神经。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1159","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"心脏的正常起搏点是？","options":["窦房结","房室结","希氏束","浦肯野纤维"],"answer":0,"explanation":"窦房结自律性最高，是正常起搏点。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1160","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"房室结位于？","options":["室间隔膜部","左心房","右心室","房间隔右侧面"],"answer":3,"explanation":"房室结位于房间隔右后部（Koch三角内）。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1161","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"心房与心室在心电图上的除极分别对应？","options":["P波与QRS波","QRS波与P波","T波与P波","P波与T波"],"answer":0,"explanation":"P波为心房除极，QRS为心室除极，T波为心室复极。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1162","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"心包腔穿刺常用的部位是？","options":["左剑肋角（剑突与左肋弓夹角）","心尖区","胸骨右缘第4肋间","腋中线第6肋间"],"answer":0,"explanation":"心包穿刺常选左剑肋角（或心尖部）。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1163","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"主动脉弓的三大分支是？","options":["右颈总、左颈总、左锁骨下","头臂干、左颈总动脉、左锁骨下动脉","头臂干、右锁骨下、左颈总","左颈总、左锁骨下、右颈总"],"answer":1,"explanation":"主动脉弓凸侧从右向左：头臂干、左颈总、左锁骨下。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1164","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"测量血压常听的动脉是？","options":["肱动脉","桡动脉","股动脉","颈总动脉"],"answer":0,"explanation":"测血压听诊肱动脉，触脉常用桡动脉。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1165","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"桡动脉的摸脉位置在？","options":["肘窝","腕尺侧","腕上方桡侧腕屈肌腱外侧","掌心"],"answer":2,"explanation":"桡动脉在腕横纹上方桡侧可触及。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1166","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"颈动脉窦的压力感受器位于？","options":["颈总动脉分叉处膨大","主动脉弓","颈内动脉颅内段","锁骨下动脉"],"answer":0,"explanation":"颈动脉窦是颈总动脉末端和颈内动脉起始部膨大，含压力感受器。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1167","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"颈动脉体（小球）的功能是？","options":["滤过器","压力感受器","化学感受器","内分泌腺"],"answer":2,"explanation":"颈动脉体感受血中O₂、CO₂、H⁺变化，为化学感受器。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1168","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脑的供血动脉是？","options":["颈外动脉和椎动脉","颈内动脉和椎动脉","颈内动脉和颈外动脉","上颌动脉和椎动脉"],"answer":1,"explanation":"脑由颈内动脉系和椎-基底动脉系供血。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1169","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"大脑动脉环（Willis环）的组成不包括？","options":["前交通动脉","大脑前动脉","大脑中动脉","后交通动脉"],"answer":2,"explanation":"Willis环由大脑前、后动脉起始段、颈内动脉末端、前/后交通动脉构成；不含大脑中动脉。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1170","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脑膜中动脉来自？","options":["颈内动脉","上颌动脉","椎动脉","面动脉"],"answer":1,"explanation":"脑膜中动脉是上颌动脉的分支，经棘孔入颅。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1171","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胃的动脉供应不来自？","options":["胃右动脉","胃左动脉","肾动脉","胃网膜右动脉"],"answer":2,"explanation":"胃的血供来自腹腔干的分支（胃左/右、网膜左/右、胃短等）。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1172","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"阑尾动脉来自？","options":["回结肠动脉","回肠动脉","右结肠动脉","肠系膜下动脉"],"answer":0,"explanation":"阑尾动脉是回结肠动脉的分支。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1173","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肠系膜上动脉不供应？","options":["十二指肠以下空回肠","横结肠左1/3","升结肠","横结肠右2/3"],"answer":1,"explanation":"横结肠左1/3由肠系膜下动脉的分支供应。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1174","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肠系膜下动脉的分支不包括？","options":["左结肠动脉","中结肠动脉","乙状结肠动脉","直肠上动脉"],"answer":1,"explanation":"中结肠动脉来自肠系膜上动脉。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1175","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"直肠上动脉来自？","options":["肠系膜上动脉","髂内动脉","阴部内动脉","肠系膜下动脉"],"answer":3,"explanation":"直肠上动脉为肠系膜下动脉的延续。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1176","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"子宫动脉与输尿管的关系是？","options":["平行不相交","动脉在输尿管后方","动脉在输尿管前方交叉","动脉在输尿管下方"],"answer":2,"explanation":"子宫动脉从输尿管前上方跨过（桥下流水），结扎时勿伤输尿管。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1177","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"体循环起于？","options":["右心房","右心室","左心房","左心室"],"answer":3,"explanation":"体循环：左心室→主动脉→全身→右心房。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1178","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肺循环起止是？","options":["左心室起、右心房止","右心室起、左心房止","右心房起、左心室止","左心房起、右心室止"],"answer":1,"explanation":"肺循环：右心室→肺动脉→肺→肺静脉→左心房。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1179","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"卵圆窝位于？","options":["左心房","室间隔","房间隔右侧面","主动脉根部"],"answer":2,"explanation":"卵圆窝是房间隔右心房面的卵圆形凹陷，为胚胎期卵圆孔闭锁遗迹。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1180","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"室间隔缺损最常见的部位是？","options":["膜部","肌部","流出道","流入道"],"answer":0,"explanation":"室间隔膜部薄弱，是先天性室缺最好发部位。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1181","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"动脉导管未闭的解剖基础是？","options":["肺静脉异位引流","房间隔缺损","室间隔缺损","主动脉与肺动脉之间的导管未闭锁"],"answer":3,"explanation":"胎儿期动脉导管连接肺动脉与主动脉，出生后应闭锁为动脉韧带。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1182","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"全身最大的淋巴器官是？","options":["脾","肝","淋巴结","胸腺"],"answer":0,"explanation":"脾是最大的淋巴器官，位于左季肋区。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1183","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脾的位置在？","options":["腹上区","右季肋区","左季肋区","左腰区"],"answer":2,"explanation":"脾位于左季肋区，第9~11肋深面，长轴与第10肋一致。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1184","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胸腺的退化时间主要在？","options":["出生时","婴幼儿期","青春期后","老年期"],"answer":2,"explanation":"胸腺在青春期后逐渐退化，被脂肪组织替代。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1185","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"淋巴系统的主要功能不包括？","options":["运输脂肪","回流组织液","免疫防御","分泌消化酶"],"answer":3,"explanation":"淋巴系统回流组织液、运输脂肪、参与免疫；不分泌消化酶。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1186","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"右淋巴导管收集的范围不包括？","options":["右头颈部","左下肢","右上肢","右胸部"],"answer":1,"explanation":"右淋巴导管收集右上肢、右头颈、右胸；左下肢属胸导管。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1187","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胸导管注入的静脉是？","options":["上腔静脉","右静脉角","左静脉角","奇静脉"],"answer":2,"explanation":"胸导管汇入左静脉角，收集全身约3/4淋巴。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1188","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"乳糜胸的原因是？","options":["胸导管损伤","气管损伤","食管破裂","主动脉破裂"],"answer":0,"explanation":"胸导管损伤致乳糜漏入胸腔，称乳糜胸。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1189","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"心包横窦的临床意义是？","options":["肿瘤好发处","心包积液积聚处","穿刺部位","心脏手术阻断血流的通道"],"answer":3,"explanation":"横窦位于主动脉、肺动脉后方，是术中阻断大血管的通道。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1190","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"冠脉循环的特点是？","options":["舒张期供血为主","收缩期供血为主","与心动周期无关","只供应心房"],"answer":0,"explanation":"冠脉在心舒张期灌注为主，舒张压高低直接影响心肌供血。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1191","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"心肌梗死最常见的原因是？","options":["冠状动脉粥样硬化","心肌炎","瓣膜病","高血压"],"answer":0,"explanation":"冠脉粥样硬化斑块破裂血栓形成是心梗最常见原因。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1192","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"心的静脉大部分经？","options":["下腔静脉","上腔静脉","肺静脉","冠状静脉窦回流入右心房"],"answer":3,"explanation":"心大、中、小静脉汇入冠状窦，开口于右心房。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1193","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"动脉韧带位于？","options":["主动脉弓下缘与肺动脉分叉之间","升主动脉与上腔静脉之间","肺静脉之间","上下腔静脉之间"],"answer":0,"explanation":"动脉韧带是胎儿动脉导管闭锁后的遗迹。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1194","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"体表可触及的动脉搏动不包括？","options":["肋间动脉","桡动脉","肱动脉","股动脉"],"answer":0,"explanation":"肋间动脉位置深不可触及；桡、肱、股、颈、足背等可触及。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1195","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"神经系统的基本结构和功能单位是？","options":["神经元","神经纤维","突触","胶质细胞"],"answer":0,"explanation":"神经元是神经系统的基本结构和功能单位。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1196","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"中枢神经系统包括？","options":["脑和脑神经","脑和脊髓","脊髓和脊神经","脑干和小脑"],"answer":1,"explanation":"中枢=脑+脊髓；周围=脑神经+脊神经+内脏神经。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1197","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"成人的脊髓末端约平？","options":["第1腰椎下缘","第2骶椎","第12胸椎上缘","第3腰椎"],"answer":0,"explanation":"新生儿脊髓止于第3腰椎，成人止于第1腰椎下缘。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1198","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"马尾由什么构成？","options":["终丝","脊髓圆锥","腰骶尾神经根","硬脊膜"],"answer":2,"explanation":"腰骶尾神经根在椎管内下行围绕终丝形成马尾。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1199","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脊髓的灰质前角含？","options":["交感节前神经元","感觉神经元","运动神经元","副交感神经元"],"answer":2,"explanation":"前角为运动神经元（前角运动细胞），后角为中间/联络神经元。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1200","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脊髓灰质侧角的交感节前神经元位于？","options":["第2~4骶髓","第1胸髓至第3腰髓","颈髓","第4~5腰髓"],"answer":1,"explanation":"脊髓侧角（T1~L3）含交感节前神经元；S2~4含副交感节前神经元。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1201","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"薄束和楔束的功能是？","options":["传导同侧本体感觉和精细触觉","传导痛温觉","传导对侧本体感觉","传导粗触觉"],"answer":0,"explanation":"薄楔束上行传导同侧意识性本体感觉与精细触觉。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1202","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脊髓丘脑束传导？","options":["同侧精细触觉","同侧本体感觉","对侧痛温觉和粗触觉","对侧本体感觉"],"answer":2,"explanation":"脊髓丘脑束交叉后上行，传导对侧躯体的痛温觉和粗触觉。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1203","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脑干包括？","options":["小脑、脑桥、延髓","间脑、中脑、延髓","中脑、脑桥、延髓","中脑、间脑、小脑"],"answer":2,"explanation":"脑干自上而下为中脑、脑桥、延髓。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1204","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"生命中枢位于？","options":["延髓","脑桥","中脑","下丘脑"],"answer":0,"explanation":"延髓内有呼吸、心血管等基本生命中枢。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1205","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"瞳孔对光反射的中枢位于？","options":["中脑","延髓","脑桥","间脑"],"answer":0,"explanation":"瞳孔对光反射中枢在中脑顶盖（上丘/顶盖前区）。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1206","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"角膜反射的传入神经是？","options":["三叉神经","面神经","动眼神经","视神经"],"answer":0,"explanation":"角膜反射：三叉神经传入，面神经传出。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1207","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"小脑的功能不包括？","options":["维持平衡","协调运动","产生意识性感觉","调节肌张力"],"answer":2,"explanation":"小脑协调运动、维持平衡、调节肌张力；不产生意识性感觉。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1208","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"小脑扁桃体疝（枕骨大孔疝）的后果是？","options":["压迫中脑","压迫延髓危及生命","压迫脑桥","压迫间脑"],"answer":1,"explanation":"颅内压增高时小脑扁桃体疝入枕骨大孔，压迫延髓生命中枢。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1209","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"间脑中与内脏活动调节有关的是？","options":["丘脑","下丘脑","上丘脑","后丘脑"],"answer":1,"explanation":"下丘脑是内脏活动（体温、摄食、水平衡、内分泌）的调节中枢。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1210","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"大脑皮层躯体运动区位于？","options":["颞横回","中央后回","中央前回和中央旁小叶前部","距状沟周围"],"answer":2,"explanation":"第Ⅰ躯体运动区在中央前回及中央旁小叶前部；感觉区在中央后回。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1211","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"大脑皮层躯体感觉区位于？","options":["额下回","中央前回","角回","中央后回和中央旁小叶后部"],"answer":3,"explanation":"第Ⅰ躯体感觉区在中央后回及中央旁小叶后部。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1212","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"视觉区位于？","options":["颞横回","距状沟周围皮质","角回","中央后回"],"answer":1,"explanation":"视觉中枢在枕叶距状沟周围；听觉在颞横回。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1213","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"运动性语言中枢（说话中枢）位于？","options":["额中回后部","颞上回后部","角回","额下回后部（Broca区）"],"answer":3,"explanation":"Broca区在额下回后部，损伤致运动性失语（能听懂不能说）。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1214","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"内囊位于？","options":["胼胝体上方","豆状核与屏状核之间","丘脑、尾状核与豆状核之间","侧脑室内"],"answer":2,"explanation":"内囊是丘脑、尾状核与豆状核之间的白质板。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1215","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"内囊出血的典型表现是？","options":["三偏征（偏瘫、偏身感觉障碍、偏盲）","单瘫","截瘫","交叉瘫"],"answer":0,"explanation":"内囊损伤致对侧三偏征。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1216","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脑脊液的产生部位主要是？","options":["硬脑膜窦","蛛网膜粒","脉络丛","室管膜"],"answer":2,"explanation":"脑脊液主要由各脑室脉络丛产生。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1217","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脑脊液回收入血的部位是？","options":["室管膜","脉络丛","蛛网膜粒渗入上矢状窦","软脑膜"],"answer":2,"explanation":"脑脊液经蛛网膜粒渗入上矢状窦回流静脉。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1218","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"正常成人脑脊液总量约？","options":["30ml","500ml","150ml（100~160ml）","1000ml"],"answer":2,"explanation":"成人脑脊液总量约150ml，不断产生循环更新。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1219","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"腰椎穿刺抽取脑脊液常选？","options":["第5腰椎与骶椎间","第1、2腰椎间隙","第3、4腰椎间隙","第12胸椎间隙"],"answer":2,"explanation":"成人脊髓止于第1腰椎下缘，L3~4间隙穿刺安全。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1220","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"第1对脑神经是？","options":["滑车神经","视神经","动眼神经","嗅神经"],"answer":3,"explanation":"脑神经顺序：Ⅰ嗅、Ⅱ视、Ⅲ动眼、Ⅳ滑车、Ⅴ三叉……","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1221","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"第Ⅷ对脑神经是？","options":["前庭蜗神经","面神经","舌咽神经","迷走神经"],"answer":0,"explanation":"Ⅷ为前庭蜗（位听）神经。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1222","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"损伤后出现舌肌萎缩和伸舌偏向患侧的是？","options":["舌咽神经","舌下神经","面神经","三叉神经"],"answer":1,"explanation":"舌下神经支配舌肌，损伤后患侧舌肌萎缩、伸舌偏向患侧。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1223","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"面神经的功能不包括？","options":["泪腺和唾液分泌","支配表情肌","舌前2/3味觉","支配咀嚼肌"],"answer":3,"explanation":"咀嚼肌由三叉神经（下颌神经）支配。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1224","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"三叉神经的下颌神经是？","options":["副交感","纯感觉","纯运动","混合性神经"],"answer":3,"explanation":"眼支、上颌支为感觉性，下颌支为混合性。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1225","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"迷走神经的功能不包括？","options":["传导内脏感觉","支配咽喉肌","支配胸腹腔脏器","支配咀嚼肌"],"answer":3,"explanation":"迷走神经支配咽喉肌和胸腹腔脏器（至横结肠左曲附近）；不支配咀嚼肌。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1226","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"交感神经的低级中枢位于？","options":["骶髓","脑干","脊髓第1胸髓至第3腰髓","大脑"],"answer":2,"explanation":"交感低级中枢在T1~L3侧角；副交感在脑干和S2~4。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1227","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"副交感神经的低级中枢位于？","options":["脑干和脊髓第2~4骶节","胸腰段脊髓","交感干","肾上腺髓质"],"answer":0,"explanation":"副交感中枢在脑干（Ⅲ、Ⅶ、Ⅸ、Ⅹ）和S2~4。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1228","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"交感神经兴奋的表现不包括？","options":["支气管扩张","心跳加快","瞳孔缩小","血糖升高"],"answer":2,"explanation":"交感兴奋瞳孔散大；瞳孔缩小是副交感表现。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1229","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"内脏神经的特点是？","options":["不含感觉纤维","完全受意识支配","只含运动纤维","受意识支配不完全"],"answer":3,"explanation":"内脏神经（自主神经）活动不完全受意识控制，含运动和感觉纤维。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1230","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"大脑的动脉供血中，大脑中动脉供血区是？","options":["枕叶后部","大脑半球内侧面","大脑半球背外侧面大部分","小脑"],"answer":2,"explanation":"大脑中动脉供应背外侧面大部（含运动、感觉、语言区），内侧面主要为大脑前动脉。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1231","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脑疝的类型不包括？","options":["枕骨大孔疝","小脑幕切迹上疝","小脑幕切迹疝","大脑镰下疝"],"answer":1,"explanation":"常见脑疝：小脑幕切迹疝（下疝）、枕骨大孔疝、大脑镰下疝；无切迹上疝。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1232","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"小脑幕切迹疝的典型表现是？","options":["同侧偏瘫","双侧瞳孔缩小","患侧瞳孔散大、对侧偏瘫","失语"],"answer":2,"explanation":"动眼神经受压致患侧瞳孔散大，锥体束受压致对侧偏瘫。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1233","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脊髓的被膜由外向内是？","options":["软脊膜、蛛网膜、硬脊膜","硬脊膜、蛛网膜、软脊膜","蛛网膜、硬脊膜、软脊膜","硬脊膜、软脊膜、蛛网膜"],"answer":1,"explanation":"脊髓三层被膜由外向内：硬膜、蛛网膜、软膜。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1234","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"硬膜外麻醉的穿刺层次是？","options":["硬脊膜外隙","蛛网膜下隙","软脊膜下","硬膜下隙"],"answer":0,"explanation":"硬膜外麻醉注药于硬脊膜外隙；腰麻注药于蛛网膜下隙。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1235","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脑和脊髓的被膜之间充满脑脊液的间隙是？","options":["硬膜下隙","硬膜外隙","蛛网膜下隙","软膜下隙"],"answer":2,"explanation":"蛛网膜与软膜之间的蛛网膜下隙充满脑脊液。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1236","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"锥体系的组成是？","options":["上、下两级运动神经元","三级神经元","仅皮质","仅脊髓前角"],"answer":0,"explanation":"锥体系=上运动神经元（皮质）+下运动神经元（脑干/脊髓前角）。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1237","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"上运动神经元瘫痪的特点是？","options":["肌萎缩明显","肌张力降低、腱反射消失","肌张力增高、腱反射亢进、病理征阳性","弛缓性瘫痪"],"answer":2,"explanation":"上运动神经元瘫（中枢性瘫）表现为硬瘫；下运动神经元瘫为软瘫。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1238","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"下运动神经元瘫痪的特点是？","options":["肌张力增高","肌张力降低、腱反射消失、肌萎缩明显","病理征阳性","痉挛性瘫痪"],"answer":1,"explanation":"下运动神经元瘫（周围性瘫）为软瘫，伴肌萎缩和肌束颤动。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1239","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"瞳孔对光反射的传出神经是？","options":["三叉神经","视神经","动眼神经","面神经"],"answer":2,"explanation":"光反射弧：视神经传入→中脑→动眼神经（副交感）传出缩瞳。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1240","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"人体最大的内分泌腺是？","options":["性腺","垂体","肾上腺","甲状腺"],"answer":3,"explanation":"甲状腺是最大的内分泌腺，重约25g。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1241","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"甲状腺分泌的激素是？","options":["甲状旁腺素","甲状腺激素（T3、T4）","降钙素以外的类固醇","肾上腺素"],"answer":1,"explanation":"甲状腺滤泡上皮分泌T3/T4；滤泡旁细胞分泌降钙素。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1242","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"甲状旁腺素的主要作用是？","options":["降低血钙","升高血钙","升高血磷","抑制骨吸收"],"answer":1,"explanation":"PTH促进骨钙释放和肾小管钙重吸收，升高血钙、降低血磷。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1243","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"降钙素的分泌细胞是？","options":["滤泡上皮细胞","甲状腺滤泡旁细胞（C细胞）","甲状旁腺主细胞","肾上腺皮质"],"answer":1,"explanation":"降钙素由甲状腺滤泡旁细胞分泌，降低血钙。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1244","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"垂体分为？","options":["结节部和中间部","前叶和后叶（仅按位置）","漏斗部和远侧部","腺垂体和神经垂体"],"answer":3,"explanation":"垂体分腺垂体（前叶为主）和神经垂体（后叶）。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1245","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"生长激素分泌的腺体是？","options":["神经垂体","腺垂体","甲状腺","肾上腺"],"answer":1,"explanation":"生长激素由腺垂体嗜酸性细胞分泌。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1246","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"神经垂体释放的激素是？","options":["抗利尿激素和催产素","生长激素和催乳素","促甲状腺激素","促肾上腺皮质激素"],"answer":0,"explanation":"ADH（血管加压素）和催产素由下丘脑合成、神经垂体储存释放。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1247","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"抗利尿激素分泌不足导致的疾病是？","options":["尿崩症","巨人症","库欣综合征","甲亢"],"answer":0,"explanation":"ADH缺乏致肾小管重吸收水障碍，出现尿崩症。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1248","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾上腺皮质由外向内分泌的激素依次是？","options":["盐皮质激素、糖皮质激素、性激素","糖皮质激素、盐皮质激素、性激素","性激素、糖皮质激素、盐皮质激素","盐皮质激素、性激素、糖皮质激素"],"answer":0,"explanation":"球状带→盐皮质激素（醛固酮）；束状带→糖皮质激素；网状带→性激素。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1249","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"糖皮质激素的主要生理作用不包括？","options":["升高血糖","促进蛋白质合成","抗炎","抗过敏"],"answer":1,"explanation":"糖皮质激素促进蛋白质分解（而非合成）、升糖、抗炎抗过敏抗休克。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1250","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾上腺髓质分泌的激素是？","options":["雄激素","皮质醇","醛固酮","肾上腺素和去甲肾上腺素"],"answer":3,"explanation":"髓质嗜铬细胞分泌儿茶酚胺（肾上腺素、去甲肾上腺素）。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1251","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胰岛的细胞中分泌胰岛素的是？","options":["PP细胞","A细胞（α细胞）","D细胞","B细胞（β细胞）"],"answer":3,"explanation":"β细胞分泌胰岛素；α细胞分泌胰高血糖素。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1252","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胰岛素的主要作用是？","options":["抑制葡萄糖利用","升高血糖","促进糖异生","降低血糖"],"answer":3,"explanation":"胰岛素促进组织摄取利用葡萄糖，是唯一降糖激素。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1253","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胰岛素缺乏导致的疾病是？","options":["甲亢","低血糖症","糖尿病","尿崩症"],"answer":2,"explanation":"1型糖尿病因胰岛素绝对缺乏。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1254","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"松果体分泌的激素是？","options":["催产素","生长激素","褪黑素","甲状腺素"],"answer":2,"explanation":"松果体分泌褪黑素，参与昼夜节律调节。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1255","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"激素作用的特点不包括？","options":["高效能","只作用于固定靶器官","特异性","信使传递"],"answer":1,"explanation":"激素随血液流经全身，作用于有受体的靶细胞，不固定于某一器官。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1256","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"下丘脑与腺垂体的功能联系通过？","options":["垂体柄神经纤维","垂体门脉系统","淋巴管","血液直接混合"],"answer":1,"explanation":"下丘脑促垂体区经垂体门脉系统调节腺垂体。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1257","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"下丘脑与神经垂体的联系通过？","options":["蛛网膜","垂体门脉","下丘脑-垂体束","室管膜"],"answer":2,"explanation":"下丘脑视上核、室旁核经下丘脑-垂体束与神经垂体联系。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1258","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"甲状腺激素的合成原料是？","options":["铁和酪氨酸","碘和色氨酸","碘和酪氨酸","钙和磷"],"answer":2,"explanation":"甲状腺激素以碘和酪氨酸为原料合成。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1259","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"地方性甲状腺肿的主要原因是？","options":["甲状腺炎","甲亢","缺碘","遗传"],"answer":2,"explanation":"缺碘致甲状腺激素合成不足，TSH代偿性增多致甲状腺肿大。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1260","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"呆小症的病因是？","options":["幼年甲状腺激素分泌不足","幼年生长激素不足","成年甲状腺激素不足","成年生长激素过多"],"answer":0,"explanation":"幼年甲状腺激素缺乏致呆小症（智力+体格发育障碍）；生长激素缺乏致侏儒症。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1261","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"侏儒症的病因是？","options":["幼年甲状腺激素不足","幼年生长激素分泌不足","成年生长激素过多","垂体肿瘤"],"answer":1,"explanation":"幼年GH缺乏致身材矮小但智力正常，称垂体性侏儒。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1262","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"巨人症的病因是？","options":["成年生长激素过多","幼年生长激素分泌过多","甲状腺激素过多","胰岛素过多"],"answer":1,"explanation":"幼年GH过多致巨人症；成年GH过多致肢端肥大症。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1263","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肢端肥大症的病因是？","options":["糖皮质激素过多","幼年生长激素过多","成年生长激素分泌过多","醛固酮过多"],"answer":2,"explanation":"成年骨骺已闭合，GH过多致肢端骨增生为肢端肥大症。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1264","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"应激反应时明显升高的激素不包括？","options":["糖皮质激素","胰岛素","肾上腺素","去甲肾上腺素"],"answer":1,"explanation":"应激时儿茶酚胺、糖皮质激素、生长激素等升高；胰岛素分泌受抑制。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1265","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"眼球壁的外层（纤维膜）包括？","options":["虹膜和睫状体","角膜和巩膜","视网膜","脉络膜"],"answer":1,"explanation":"眼球壁外层=角膜+巩膜；中层=虹膜、睫状体、脉络膜；内层=视网膜。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1266","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"眼的屈光系统不包括？","options":["晶状体","角膜","房水","视网膜"],"answer":3,"explanation":"屈光系统=角膜、房水、晶状体、玻璃体；视网膜是感光结构。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1267","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"房水由什么产生？","options":["脉络膜","虹膜","睫状体","巩膜"],"answer":2,"explanation":"房水由睫状体产生，经后房→瞳孔→前房→前房角回流。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1268","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"青光眼的主要原因是？","options":["房水回流受阻、眼压升高","晶状体混浊","视网膜脱离","角膜穿孔"],"answer":0,"explanation":"房水循环受阻致眼压升高，损伤视神经为青光眼。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1269","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"白内障的病变部位是？","options":["玻璃体","角膜","晶状体","视网膜"],"answer":2,"explanation":"晶状体混浊称白内障。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1270","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"视网膜上感光最敏锐的部位是？","options":["视神经盘","黄斑中央凹","视网膜周边","锯状缘"],"answer":1,"explanation":"中央凹只有视锥细胞，感光最敏锐；视神经盘无感光细胞为生理盲点。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1271","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"视神经盘（视乳头）的特点是？","options":["位于黄斑中心","感光最敏锐","只有视杆细胞","无感光细胞，为生理盲点"],"answer":3,"explanation":"视神经盘是视神经穿出处，无视细胞，为生理盲点。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1272","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"视杆细胞的功能是？","options":["感受颜色","感受强光和颜色","感受弱光（暗视觉）","调节晶状体"],"answer":2,"explanation":"视杆细胞感受弱光，无色觉；视锥细胞感受强光和色觉。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1273","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"近视眼的原因是？","options":["角膜变平","眼球前后径过短","晶状体变薄","眼球前后径过长或屈光力过强"],"answer":3,"explanation":"近视眼焦点落在视网膜前，多因眼轴过长。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1274","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"远视眼的原因是？","options":["角膜变凸","眼球前后径过长","晶状体变厚","眼球前后径过短"],"answer":3,"explanation":"远视眼焦点落在视网膜后，多因眼轴过短。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1275","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"老视（老花眼）的原因是？","options":["眼轴变长","晶状体弹性减退","角膜混浊","玻璃体液化"],"answer":1,"explanation":"年龄增长晶状体弹性下降，看近物调节能力减弱。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1276","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"鼓膜的位置是？","options":["外耳道与内耳之间","内耳与中耳的分界","外耳道与中耳的分界","鼻咽部"],"answer":2,"explanation":"鼓膜分隔外耳道与中耳（鼓室）。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1277","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"听觉感受器是？","options":["螺旋器（Corti器）","椭圆囊斑","球囊斑","壶腹嵴"],"answer":0,"explanation":"螺旋器位于蜗管基底膜，是听觉感受器；壶腹嵴感受旋转。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1278","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"平衡觉感受器不包括？","options":["椭圆囊斑","耳蜗","球囊斑","壶腹嵴"],"answer":1,"explanation":"耳蜗司听觉；囊斑感受直线加速，壶腹嵴感受旋转。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1279","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"咽鼓管的功能不包括？","options":["引流分泌物","平衡鼓室内外气压","产生听觉","阻隔自身声音（开放时）"],"answer":2,"explanation":"咽鼓管连通鼓室与鼻咽，平衡气压、引流；不产生听觉。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1280","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"细胞膜的化学组成主要是？","options":["糖类和核酸","脂质和蛋白质","核酸和蛋白质","水和电解质"],"answer":1,"explanation":"细胞膜以脂质（磷脂为主）和蛋白质为基本组成，含少量糖类。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1281","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"细胞膜的物质转运中，O₂和CO₂进入细胞的方式是？","options":["胞吞","易化扩散","主动转运","单纯扩散"],"answer":3,"explanation":"脂溶性小分子（O₂、CO₂、N₂等）经单纯扩散通过细胞膜。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1282","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"葡萄糖进入红细胞的方式是？","options":["易化扩散（载体介导）","单纯扩散","主动转运","胞饮"],"answer":0,"explanation":"葡萄糖经载体蛋白顺浓度梯度易化扩散进入红细胞。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1283","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"Na⁺-K⁺泵的活动属于？","options":["被动转运","主动转运（原发性）","易化扩散","膜泡运输"],"answer":1,"explanation":"Na⁺-K⁺泵直接消耗ATP逆浓度梯度转运，为原发性主动转运。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1284","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"静息电位的产生主要是由于？","options":["K⁺外流","Na⁺内流","Cl⁻内流","Ca²⁺内流"],"answer":0,"explanation":"静息电位主要是K⁺顺浓度梯度经漏通道外流形成的K⁺平衡电位。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1285","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"动作电位的上升支（去极相）主要是由于？","options":["Ca²⁺外流","K⁺外流","Cl⁻外流","Na⁺内流"],"answer":3,"explanation":"动作电位上升支是Na⁺经电压门控通道快速内流所致。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1286","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"动作电位传导的特点是？","options":["可以总和","衰减性传导","不衰减（全或无）","有等级性"],"answer":2,"explanation":"动作电位幅度恒定（全或无），传导不衰减。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1287","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"血细胞中数量最多的是？","options":["血小板","白细胞","红细胞","淋巴细胞"],"answer":2,"explanation":"红细胞正常男性约(4.0~5.5)×10¹²/L，是数量最多的血细胞。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1288","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"正常成人红细胞参考值（男性）是？","options":["(6.0~8.0)×10¹²/L","(3.5~5.0)×10¹²/L","(4.0~5.5)×10¹²/L","(2.0~3.0)×10¹²/L"],"answer":2,"explanation":"男性红细胞4.0~5.5×10¹²/L，女性3.5~5.0×10¹²/L。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1289","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"血红蛋白正常值（成年男性）约为？","options":["170~200g/L","100~120g/L","120~160g/L","80~100g/L"],"answer":2,"explanation":"成年男性Hb约120~160g/L，女性110~150g/L。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1290","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"ABO血型系统中，AB型红细胞上的抗原是？","options":["无抗原","只有A抗原","只有B抗原","A和B抗原"],"answer":3,"explanation":"AB型红细胞含A、B两种抗原，血浆中无抗A抗B抗体。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1291","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"O型血的血浆中含有？","options":["只有抗A抗体","抗A和抗B抗体","只有抗B抗体","无抗体"],"answer":1,"explanation":"O型红细胞无A/B抗原，血浆含抗A、抗B两种抗体。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1292","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"Rh血型系统中，我国汉族人口绝大多数为？","options":["Rh阴性","Rh阳性","各占一半","均为阴性"],"answer":1,"explanation":"汉族Rh阳性约99%以上，阴性不足1%。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1293","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"血浆渗透压的组成不包括？","options":["以晶体渗透压为主","晶体渗透压","胶体渗透压","晶体渗透压以外的胶体渗透压为主要成分"],"answer":3,"explanation":"血浆渗透压以晶体渗透压为主（约99.5%）；胶体渗透压仅约1.5mOsm。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1294","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"维持血管内外水平衡的主要因素是？","options":["血浆胶体渗透压","晶体渗透压","静水压","组织液胶渗压"],"answer":0,"explanation":"血浆胶体渗透压（白蛋白）维持血管内外水平衡；晶体渗透压维持细胞内外。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1295","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"内环境是指？","options":["细胞内液","细胞外液","血浆","组织液"],"answer":1,"explanation":"内环境=细胞外液（血浆、组织液、淋巴液等）。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1296","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"体温的生理波动不包括？","options":["年龄差异","昼夜节律","性别差异","随季节规律性大幅波动"],"answer":3,"explanation":"体温有昼夜（清晨低午后高）、性别、年龄、运动等波动；无季节性大幅波动。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1297","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"体温调节的基本中枢位于？","options":["脊髓","延髓","脑桥","下丘脑"],"answer":3,"explanation":"体温调节基本中枢在下丘脑（PO/AH区）。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1298","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"安静状态下产热最多的器官是？","options":["肾脏","骨骼肌","心脏","肝脏"],"answer":3,"explanation":"安静时肝脏产热最多；运动时骨骼肌为主要产热器官。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1299","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"散热的主要方式是？","options":["只靠蒸发","辐射、传导、对流、蒸发","只靠辐射","只靠传导"],"answer":1,"explanation":"皮肤散热四种方式：辐射（安静时主要）、传导、对流、蒸发（高温时主要）。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1300","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"人体必需脂肪酸是？","options":["软脂酸","亚油酸","硬脂酸","油酸"],"answer":1,"explanation":"亚油酸和α-亚麻酸在体内不能合成，必须由食物供给，为必需脂肪酸。","exam":"医疗编","__sub":"生物化学","diff":1,"id":"yl-1301","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"蛋白质的二级结构不包括？","options":["三级结构","α-螺旋","β-折叠","β-转角"],"answer":0,"explanation":"蛋白质二级结构指肽链主链的局部空间排列，包括α-螺旋、β-折叠、β-转角和无规卷曲；三级结构是整条肽链的空间构象。","exam":"医疗编","__sub":"生物化学","diff":1,"id":"yl-1302","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"RNA水解后得到的碱基不包括？","options":["腺嘌呤","胸腺嘧啶","鸟嘌呤","尿嘧啶"],"answer":1,"explanation":"RNA含A、G、C、U四种碱基；胸腺嘧啶（T）是DNA特有的碱基。","exam":"医疗编","__sub":"生物化学","diff":1,"id":"yl-1303","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"酶促反应中决定酶特异性的是？","options":["激活剂","辅酶","金属离子","酶蛋白"],"answer":3,"explanation":"酶蛋白决定酶的专一性（特异性），辅酶/辅基主要参与传递电子、原子或基团。","exam":"医疗编","__sub":"生物化学","diff":1,"id":"yl-1304","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"糖酵解的终产物是？","options":["丙酮酸","乳酸","乙酰CoA","葡萄糖"],"answer":1,"explanation":"糖酵解在缺氧条件下终产物为乳酸；丙酮酸是糖酵解的直接中间终产物，在胞浆可进一步还原为乳酸，教材标准答案为乳酸。","exam":"医疗编","__sub":"生物化学","diff":2,"id":"yl-1305","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"三羧酸循环发生在细胞的哪个部位？","options":["高尔基体","细胞质基质","内质网","线粒体基质"],"answer":3,"explanation":"三羧酸循环的酶系分布于线粒体基质（琥珀酸脱氢酶位于线粒体内膜）。","exam":"医疗编","__sub":"生物化学","diff":1,"id":"yl-1306","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"体内生成ATP的主要方式是？","options":["磷酸戊糖途径","底物水平磷酸化","糖原分解","氧化磷酸化"],"answer":3,"explanation":"线粒体内经呼吸链氧化磷酸化生成的ATP占体内ATP生成总量的绝大部分。","exam":"医疗编","__sub":"生物化学","diff":1,"id":"yl-1307","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"血浆脂蛋白中运输内源性甘油三酯的是？","options":["HDL","CM","LDL","VLDL"],"answer":3,"explanation":"CM运输外源性甘油三酯，VLDL运输内源性甘油三酯，LDL转运胆固醇至外周组织，HDL参与胆固醇逆向转运。","exam":"医疗编","__sub":"生物化学","diff":2,"id":"yl-1308","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"人体内氨的主要代谢去路是？","options":["合成氨基酸","以氨的形式由肺呼出","合成嘌呤碱","在肝内合成尿素随尿排出"],"answer":3,"explanation":"肝脏通过鸟氨酸循环将有毒的氨合成尿素，是氨的主要去路。","exam":"医疗编","__sub":"生物化学","diff":1,"id":"yl-1309","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"DNA复制时，催化领头链连续合成的酶是？","options":["DNA聚合酶Ⅲ（原核）","DNA聚合酶Ⅰ","引物酶","连接酶"],"answer":0,"explanation":"原核生物DNA-polⅢ是复制延长中催化核苷酸聚合的主要酶，负责领头链连续合成与随从链合成。","exam":"医疗编","__sub":"生物化学","diff":2,"id":"yl-1310","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"逆转录的模板是？","options":["DNA","RNA","mRNA","tRNA"],"answer":1,"explanation":"逆转录是以RNA为模板合成DNA的过程，由逆转录酶催化。","exam":"医疗编","__sub":"生物化学","diff":1,"id":"yl-1311","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"嘌呤核苷酸分解代谢的终产物是？","options":["肌酐","尿素","尿酸","氨"],"answer":2,"explanation":"嘌呤核苷酸在人体内分解的终产物是尿酸，随尿排出；尿酸生成过多可致痛风。","exam":"医疗编","__sub":"生物化学","diff":1,"id":"yl-1312","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"生物氧化中能直接与氧结合的细胞色素是？","options":["细胞色素b","细胞色素aa₃","细胞色素c₁","细胞色素c"],"answer":1,"explanation":"细胞色素aa₃即细胞色素c氧化酶，可将电子直接传递给氧，是呼吸链末端。","exam":"医疗编","__sub":"生物化学","diff":2,"id":"yl-1313","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"竞争性抑制剂对酶促反应的影响是？","options":["Km降低，Vmax不变","Km不变，Vmax降低","Km增大，Vmax不变","Km与Vmax均降低"],"answer":2,"explanation":"竞争性抑制剂与底物竞争酶活性中心，表观Km增大，Vmax不变；非竞争性抑制剂则Vmax降低、Km不变。","exam":"医疗编","__sub":"生物化学","diff":2,"id":"yl-1314","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"体内胆固醇合成的关键酶是？","options":["HMG-CoA合酶","HMG-CoA还原酶","乙酰CoA羧化酶","柠檬酸合酶"],"answer":1,"explanation":"肝内HMG-CoA还原酶是胆固醇合成的限速酶，他汀类药物即抑制此酶。","exam":"医疗编","__sub":"生物化学","diff":2,"id":"yl-1315","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"血糖的主要来源不包括？","options":["肝糖原分解","肌糖原直接分解入血","糖异生","食物中糖类消化吸收"],"answer":1,"explanation":"肌糖原缺乏葡萄糖-6-磷酸酶，不能直接分解成葡萄糖入血，只能进行糖酵解或有氧氧化供能。","exam":"医疗编","__sub":"生物化学","diff":2,"id":"yl-1316","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"酮体包括乙酰乙酸、β-羟丁酸和？","options":["丙酮","乳酸","丙酮酸","草酰乙酸"],"answer":0,"explanation":"酮体是肝内脂肪酸氧化的正常中间产物，包括乙酰乙酸、β-羟丁酸和丙酮。","exam":"医疗编","__sub":"生物化学","diff":1,"id":"yl-1317","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"mRNA上的密码子共有多少个？","options":["64个","20个","61个","4个"],"answer":0,"explanation":"4种核苷酸每3个组成一个密码子，共4³=64个密码子，其中61个编码氨基酸，3个为终止密码子。","exam":"医疗编","__sub":"生物化学","diff":1,"id":"yl-1318","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"呼吸链中电子传递的最终受氢体是？","options":["CoQ","NAD⁺","FAD","氧"],"answer":3,"explanation":"呼吸链各递氢体依次传递电子，最终由氧接受电子并与氢结合生成水。","exam":"医疗编","__sub":"生物化学","diff":1,"id":"yl-1319","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"血浆清蛋白的主要功能不包括？","options":["营养作用","维持血浆胶体渗透压","运输作用","免疫防御"],"answer":3,"explanation":"血浆清蛋白主要维持胶体渗透压、参与物质运输并提供营养；免疫防御主要由免疫球蛋白承担。","exam":"医疗编","__sub":"生物化学","diff":1,"id":"yl-1320","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"细胞坏死的主要形态学标志是？","options":["线粒体增多","细胞肿胀","核固缩、核碎裂、核溶解","细胞器肥大"],"answer":2,"explanation":"坏死时细胞核出现固缩、碎裂、溶解等形态改变，是细胞坏死的重要标志。","exam":"医疗编","__sub":"病理学","diff":1,"id":"yl-1321","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"最常见类型的脑梗死属于？","options":["败血性梗死","出血性梗死","贫血性梗死","混合性梗死"],"answer":2,"explanation":"脑组织结构致密、侧支循环少，其梗死多为贫血性（白色）梗死；出血性梗死多见于肺、肠等双重血供器官。","exam":"医疗编","__sub":"病理学","diff":2,"id":"yl-1322","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肉芽组织的主要成分是？","options":["新生毛细血管和成纤维细胞","神经纤维和淋巴细胞","胶原纤维和软骨细胞","平滑肌和弹力纤维"],"answer":0,"explanation":"肉芽组织由新生毛细血管、成纤维细胞及少量炎细胞构成，是创伤修复的基础。","exam":"医疗编","__sub":"病理学","diff":1,"id":"yl-1323","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"血栓形成的最常见原因是？","options":["涡流形成","血流缓慢","血液凝固性增高","心血管内膜损伤"],"answer":3,"explanation":"血管内皮细胞损伤暴露内皮下胶原，激活血小板和凝血系统，是血栓形成最重要最常见的原因。","exam":"医疗编","__sub":"病理学","diff":2,"id":"yl-1324","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"炎症局部的基本病变是？","options":["充血、渗出、机化","充血、水肿、坏死","变性、坏死、再生","变质、渗出、增生"],"answer":3,"explanation":"炎症的基本病理变化包括变质、渗出和增生，其中渗出是炎症最具特征性的变化。","exam":"医疗编","__sub":"病理学","diff":1,"id":"yl-1325","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"化脓性炎以哪种细胞浸润为主？","options":["中性粒细胞","嗜酸性粒细胞","淋巴细胞","浆细胞"],"answer":0,"explanation":"化脓性炎以中性粒细胞大量浸润为主，并伴有不同程度的组织坏死和脓液形成。","exam":"医疗编","__sub":"病理学","diff":1,"id":"yl-1326","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肿瘤的异型性主要反映了肿瘤的？","options":["血液供应","生长速度","良恶性程度","遗传来源"],"answer":2,"explanation":"肿瘤组织在细胞和组织结构上与其起源的正常组织存在差异，异型性大小是诊断肿瘤、区别良恶性的主要组织学依据。","exam":"医疗编","__sub":"病理学","diff":2,"id":"yl-1327","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"癌与肉瘤最主要的区别是？","options":["发病年龄","有无转移","生长部位","组织来源不同"],"answer":3,"explanation":"癌来源于上皮组织，肉瘤来源于间叶组织，这是二者最根本的区别。","exam":"医疗编","__sub":"病理学","diff":1,"id":"yl-1328","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"动脉粥样硬化病变主要累及？","options":["大、中动脉","细小动脉","静脉","毛细血管"],"answer":0,"explanation":"动脉粥样硬化主要累及大中型动脉（如主动脉、冠状动脉、脑动脉），病变以脂质沉积和纤维帽形成为特征。","exam":"医疗编","__sub":"病理学","diff":1,"id":"yl-1329","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"高血压病最严重的并发症是？","options":["蛋白尿","左心室肥大","视网膜出血","脑出血"],"answer":3,"explanation":"脑出血是高血压最严重且往往致命的并发症，多发生于基底节区（豆纹动脉供血区）。","exam":"医疗编","__sub":"病理学","diff":1,"id":"yl-1330","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"风湿病具有诊断意义的病变是？","options":["环形红斑","纤维素样坏死","疣状心内膜炎","Aschoff小体形成"],"answer":3,"explanation":"风湿小体（Aschoff小体）是风湿病的特征性病变，具有诊断意义，主要见于心肌间质。","exam":"医疗编","__sub":"病理学","diff":2,"id":"yl-1331","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"大叶性肺炎的病原体主要是？","options":["肺炎链球菌","金黄色葡萄球菌","肺炎克雷伯菌","溶血性链球菌"],"answer":0,"explanation":"大叶性肺炎主要由肺炎链球菌引起，病变以肺泡内大量纤维素渗出为特征，多累及一个肺段或肺叶。","exam":"医疗编","__sub":"病理学","diff":1,"id":"yl-1332","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"硅肺的特征性病变是？","options":["肺肉质变","硅结节形成","干酪样坏死","肺气肿"],"answer":1,"explanation":"硅肺的基本病变是硅结节（细胞性结节→纤维性结节）形成和肺组织弥漫性纤维化。","exam":"医疗编","__sub":"病理学","diff":2,"id":"yl-1333","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"消化性溃疡最常发生的部位是？","options":["空肠","食管下段","十二指肠球部和胃窦部","结肠"],"answer":2,"explanation":"胃和十二指肠溃疡最常见，好发于十二指肠球部前壁和胃窦部小弯侧。","exam":"医疗编","__sub":"病理学","diff":1,"id":"yl-1334","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"病毒性肝炎肝细胞最常见的变性是？","options":["气球样变","脂肪变","水样变仅见于重型","玻璃样变"],"answer":0,"explanation":"急性普通型肝炎肝细胞广泛气球样变（细胞肿大、胞质疏松化），是病毒性肝炎最常见的变性形式。","exam":"医疗编","__sub":"病理学","diff":2,"id":"yl-1335","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"伤寒肠道溃疡的长轴与肠管的关系是？","options":["与肠长轴平行","与肠长轴垂直","环形深大溃疡","不规则浅表溃疡"],"answer":0,"explanation":"伤寒溃疡发生于回肠末端集合淋巴小结，其长轴与肠管长轴平行；结核性肠溃疡则与肠轴垂直。","exam":"医疗编","__sub":"病理学","diff":2,"id":"yl-1336","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"急性肾盂肾炎的病变性质属于？","options":["增生性炎","化脓性炎","纤维素性炎","肉芽肿性炎"],"answer":1,"explanation":"急性肾盂肾炎是细菌（多为大肠埃希菌）感染引起的肾盂、肾间质和肾小管的化脓性炎症。","exam":"医疗编","__sub":"病理学","diff":1,"id":"yl-1337","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"原位癌是指？","options":["癌细胞浸润肌层","癌细胞侵入淋巴管","癌细胞发生远处转移","癌细胞未突破基底膜"],"answer":3,"explanation":"原位癌指癌细胞局限于上皮层内、尚未突破基底膜，属于早期癌，及时治疗预后良好。","exam":"医疗编","__sub":"病理学","diff":1,"id":"yl-1338","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"结核结节中最具有诊断意义的细胞是？","options":["朗汉斯巨细胞","异物巨细胞","泡沫细胞","印戒细胞"],"answer":0,"explanation":"结核结节由上皮样细胞、朗汉斯巨细胞及外周淋巴细胞构成，中央可有干酪样坏死；朗汉斯巨细胞是结核病的特征性细胞。","exam":"医疗编","__sub":"病理学","diff":2,"id":"yl-1339","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"细胞水肿发生的主要机制是？","options":["线粒体受损致ATP生成减少、钠泵功能障碍","溶酶体破裂","核糖体增多","内质网扩张"],"answer":0,"explanation":"缺血缺氧等致线粒体氧化磷酸化障碍、ATP减少，细胞膜钠钾泵功能障碍，钠水潴留引起细胞水肿。","exam":"医疗编","__sub":"病理学","diff":2,"id":"yl-1340","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"药物从给药部位吸收入血后，首次经肠道和肝脏被代谢减少的现象称为？","options":["肝肠循环","首过消除","生物转化","酶诱导"],"answer":1,"explanation":"口服药物经胃肠吸收后经门静脉入肝，部分被代谢灭活，称首过消除，故口服生物利用度降低。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1341","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"药物半衰期（t1/2）是指？","options":["药物作用最强的时间","药物被完全清除所需的时间","药物起效所需的时间","血浆药物浓度下降一半所需的时间"],"answer":3,"explanation":"半衰期反映药物消除速度，是确定给药间隔的重要依据。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1342","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"一级动力学消除的特点是？","options":["单位时间内按恒定量消除","单位时间内按恒定比例消除","消除速度与剂量无关","半衰期随剂量增大而延长"],"answer":1,"explanation":"一级动力学消除中，单位时间消除恒定比例的药物，半衰期恒定。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1343","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"药物的不良反应是指？","options":["正常剂量下出现的与用药目的无关的作用","用药剂量过大引起的毒性反应","药物引起的过敏反应","药物依赖引起的戒断症状"],"answer":0,"explanation":"不良反应是治疗剂量下固有的作用，毒性反应、过敏反应等属于其他类型药源性疾病。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1344","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"药物的治疗指数是指？","options":["ED50/LD50的比值","LD50/ED50的比值","LD50×ED50","最大治疗量与最小治疗量之差"],"answer":1,"explanation":"治疗指数=LD50/ED50，比值越大说明药物越安全。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1345","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肝药酶诱导剂的作用是？","options":["使肝药酶活性减弱，药物代谢减慢","使肝药酶活性增强，加速自身及其他药物代谢","直接灭活药物","增加药物吸收"],"answer":1,"explanation":"苯巴比妥、苯妥英钠等为肝药酶诱导剂，可加速药物代谢，使药效减弱。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1346","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"受体拮抗药的特点是？","options":["既有亲和力又有内在活性","与受体亲和力弱而内在活性强","与受体亲和力强而无内在活性","只增强受体数量"],"answer":2,"explanation":"拮抗药能占据受体但不激活受体，表现为阻断作用。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1347","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"药物副作用的基本特点是？","options":["治疗剂量下发生、药物固有作用","剂量过大才发生","与体质异常有关","停药后必然加重"],"answer":0,"explanation":"副作用是治疗剂量下伴随治疗作用出现的固有反应，多数可预知。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1348","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"生物利用度是指？","options":["药物与血浆蛋白结合的比例","药物在肝脏代谢的比例","药物吸收进入体循环的相对量和速度","药物经肾排出的比例"],"answer":2,"explanation":"生物利用度反映制剂被吸收进入体循环的程度与速度。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1349","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"某药按一级动力学消除，其半衰期为4小时，单次给药后约经多少时间基本消除干净（约5个半衰期）？","options":["20小时","4小时","8小时","40小时"],"answer":0,"explanation":"约经5个半衰期（4×5=20小时）药物基本消除完毕。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1350","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"两种药物合用后作用增强称为？","options":["协同作用","拮抗作用","耐受性","依赖性"],"answer":0,"explanation":"协同作用指合用后药效增强；拮抗作用指药效减弱。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1351","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"反复用药后机体对药物的反应性降低，需增大剂量才能维持疗效，称为？","options":["耐受性","耐药性","依赖性","成瘾性"],"answer":0,"explanation":"耐受性指机体对药物反应性降低；耐药性指病原体或肿瘤细胞对药物敏感性降低。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1352","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"药物与血浆蛋白结合后，其特点是？","options":["排泄加快","药理活性增强","代谢加快","暂时失去药理活性"],"answer":3,"explanation":"结合型药物暂时无活性、不能跨膜转运和排泄，与游离型处于动态平衡。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1353","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"影响药物分布的主要因素不包括？","options":["局部器官血流量","药物与血浆蛋白结合率","体液pH值","药物的给药途径名称"],"answer":3,"explanation":"给药途径主要影响吸收，分布受蛋白结合率、pH、血流量、屏障等因素影响。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1354","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"弱酸性药物在碱性尿液中？","options":["吸收增加","排泄减慢","排泄加快","代谢停止"],"answer":2,"explanation":"弱酸性药物在碱性环境中解离增多，重吸收减少，排泄加快（如碱化尿液促巴比妥类排泄）。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1355","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"毛果芸香碱对眼睛的作用是？","options":["缩瞳、降低眼内压","扩瞳、升高眼内压","缩瞳、升高眼内压","扩瞳、降低眼内压"],"answer":0,"explanation":"毛果芸香碱激动M受体，使瞳孔括约肌收缩（缩瞳）、房水回流通畅而降低眼内压，用于青光眼。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1356","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"阿托品对眼睛的作用是？","options":["扩瞳、升高眼内压、调节麻痹","缩瞳、降低眼内压","扩瞳、降低眼内压","缩瞳、调节痉挛"],"answer":0,"explanation":"阿托品阻断M受体，使瞳孔开大肌占优势而扩瞳、房水回流受阻致眼内压升高，禁用于青光眼。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1357","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"阿托品禁用于下列哪种疾病？","options":["内脏绞痛","心动过缓","有机磷中毒","青光眼"],"answer":3,"explanation":"阿托品升高眼内压，青光眼患者禁用。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1358","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"阿托品抢救有机磷中毒时，过量中毒的特效解救药是？","options":["毛果芸香碱（毒扁豆碱）","纳洛酮","新斯的明","阿托品本身"],"answer":0,"explanation":"阿托品中毒用M受体激动药毛果芸香碱（或毒扁豆碱）对抗，禁用新斯的明透过血脑屏障差。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1359","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"新斯的明治疗重症肌无力的机制是？","options":["抑制胆碱酯酶，使乙酰胆碱增多","激动骨骼肌N2受体","促进乙酰胆碱合成","阻断胆碱受体"],"answer":0,"explanation":"新斯的明抑制胆碱酯酶，使神经肌肉接头处乙酰胆碱蓄积，改善肌无力症状。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1360","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"新斯的明禁用于？","options":["重症肌无力","支气管哮喘和机械性肠梗阻","术后腹胀气","尿潴留"],"answer":1,"explanation":"新斯的明兴奋平滑肌，可加重哮喘和机械性肠梗阻病情，故禁用。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1361","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"治疗有机磷农药中毒，阿托品化的指征不包括？","options":["肺部啰音减少","颜面潮红、皮肤干燥","瞳孔较前扩大","瞳孔缩小如针尖"],"answer":2,"explanation":"阿托品化表现为瞳孔扩大、颜面潮红、皮肤干燥、肺部啰音减少；瞳孔缩小是中毒表现。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1362","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾上腺素抢救过敏性休克的机制不包括？","options":["抑制过敏介质释放","激动β受体兴奋心脏、扩张支气管","激动α受体升高血压","直接中和过敏原"],"answer":2,"explanation":"肾上腺素通过激动α、β受体收缩血管、兴奋心脏、扩张支气管并减少介质释放，不能中和过敏原。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1363","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"青霉素引起的过敏性休克首选急救药是？","options":["糖皮质激素","肾上腺素","抗组胺药","去甲肾上腺素"],"answer":1,"explanation":"肾上腺素是过敏性休克的首选急救药，能迅速缓解喉头水肿和支气管痉挛、升高血压。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1364","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"异丙肾上腺素的主要作用是？","options":["主要激动α受体","兴奋β受体，兴奋心脏、扩张支气管","主要阻断β受体","收缩皮肤黏膜血管"],"answer":1,"explanation":"异丙肾上腺素对β1、β2受体均有强大激动作用，用于心搏骤停、房室传导阻滞和支气管哮喘。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1365","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"去甲肾上腺素静脉滴注外漏易引起？","options":["支气管痉挛","心律失常","局部组织缺血坏死","低血压休克"],"answer":2,"explanation":"去甲肾上腺素强烈收缩血管，外漏可致局部组织缺血坏死，需及时用酚妥拉明局部拮抗。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1366","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"酚妥拉明属于？","options":["胆碱酯酶抑制药","β受体阻断药","α受体激动药","α受体阻断药"],"answer":3,"explanation":"酚妥拉明为短效α受体阻断药，用于外周血管痉挛性疾病和去甲肾上腺素外漏的解救。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1367","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"普萘洛尔禁用于？","options":["心绞痛","高血压","支气管哮喘","快速型心律失常"],"answer":2,"explanation":"普萘洛尔阻断支气管β2受体，可诱发或加重哮喘，支气管哮喘患者禁用。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1368","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"琥珀胆碱的作用特点是？","options":["非去极化型肌松药","去极化型肌松药，起效快、作用短暂","中枢性肌松药","胆碱酯酶抑制药"],"answer":1,"explanation":"琥珀胆碱为去极化型骨骼肌松弛药，静注后起效快，用于气管插管等短时操作。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1369","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"筒箭毒碱中毒的解救药是？","options":["纳洛酮","阿托品","毛果芸香碱","新斯的明"],"answer":3,"explanation":"筒箭毒碱为非去极化型肌松药，新斯的明抑制胆碱酯酶可对抗其作用。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1370","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"地西泮的主要药理作用不包括？","options":["镇痛","镇静催眠","抗惊厥","抗焦虑"],"answer":3,"explanation":"地西泮具有抗焦虑、镇静催眠、抗惊厥抗癫痫和中枢性肌松作用，无镇痛作用。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1371","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"癫痫持续状态的首选药物是？","options":["卡马西平口服","苯妥英钠口服","地西泮静脉注射","乙琥胺口服"],"answer":2,"explanation":"地西泮静注是癫痫持续状态的首选，起效快、作用可靠。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1372","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"苯妥英钠是下列哪种癫痫发作的首选药？","options":["失神小发作","大发作（强直阵挛性发作）和部分性发作","肌阵挛发作","婴儿痉挛症"],"answer":1,"explanation":"苯妥英钠是癫痫大发作和部分性发作首选；对小发作（失神）无效甚至加重。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1373","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"治疗癫痫小发作（失神发作）的首选药是？","options":["苯巴比妥","苯妥英钠","乙琥胺","卡马西平"],"answer":2,"explanation":"乙琥胺是失神发作首选药；苯妥英钠对失神发作无效。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1374","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"左旋多巴治疗帕金森病的机制是？","options":["直接激动多巴胺受体","在脑内转变为多巴胺补充递质","抑制多巴胺降解","促进多巴胺释放"],"answer":1,"explanation":"左旋多巴透过血脑屏障，在脑内经多巴脱羧酶转变为多巴胺而发挥作用。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1375","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"左旋多巴与卡比多巴合用的目的是？","options":["减少外周不良反应、增强脑内疗效","延长左旋多巴半衰期至24小时","直接激动多巴胺受体","促进左旋多巴排泄"],"answer":0,"explanation":"卡比多巴抑制外周多巴脱羧酶，使更多左旋多巴入脑，疗效增强、外周不良反应减少。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1376","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"氯丙嗪抗精神病的作用机制是？","options":["促进多巴胺释放","激动多巴胺受体","抑制5-HT受体","阻断中脑-边缘系统和中脑-皮质通路的多巴胺受体"],"answer":3,"explanation":"氯丙嗪通过阻断多巴胺受体（D2）发挥抗精神病作用，长期大量使用可致锥体外系反应。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1377","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"氯丙嗪引起的锥体外系反应不包括？","options":["帕金森综合征","静坐不能","急性肌张力障碍","体位性低血压"],"answer":0,"explanation":"体位性低血压是α受体阻断所致，不属于锥体外系反应。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1378","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"吗啡的药理作用不包括？","options":["呼吸兴奋","镇静","镇咳","镇痛"],"answer":3,"explanation":"吗啡有镇痛、镇静、镇咳、抑制呼吸等作用，对呼吸是抑制而非兴奋。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1379","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"吗啡禁用于？","options":["颅脑损伤所致颅内压增高者","心源性哮喘","严重创伤剧痛","晚期癌痛"],"answer":0,"explanation":"吗啡扩张脑血管、抑制呼吸，颅脑损伤颅内压增高者禁用；心源性哮喘可用吗啡辅助治疗。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1380","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"吗啡治疗心源性哮喘的机制不包括？","options":["增强心肌收缩力","镇静作用消除紧张情绪","降低呼吸中枢对CO2的敏感性，消除急促浅表呼吸","扩张外周血管，减轻心脏负荷"],"answer":3,"explanation":"吗啡不增强心肌收缩力，其治疗心源性哮喘靠扩血管、镇静和降低呼吸中枢兴奋性。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1381","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"哌替啶与吗啡比较，其特点是？","options":["成瘾性更强","镇痛作用更强","镇痛作用较弱、维持时间较短","抑制呼吸更明显"],"answer":2,"explanation":"哌替啶镇痛强度约为吗啡的1/10，维持时间短，是常用的人工合成镇痛药。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1382","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"纳洛酮的作用是？","options":["阿片受体拮抗药，用于吗啡类中毒解救","阿片受体激动药","胆碱受体阻断药","呼吸兴奋药"],"answer":0,"explanation":"纳洛酮竞争性阻断阿片受体，是吗啡类镇痛药急性中毒的特效解救药。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1383","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"阿司匹林解热镇痛抗炎的作用机制是？","options":["促进前列腺素合成","抑制前列腺素（PG）合成","阻断阿片受体","抑制组胺释放"],"answer":1,"explanation":"阿司匹林抑制环氧化酶（COX），减少前列腺素合成而发挥解热镇痛抗炎作用。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1384","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"小剂量阿司匹林预防血栓的机制是？","options":["促进纤溶","抑制血小板环氧化酶，减少血栓素A2生成","抑制凝血酶","增强血小板聚集"],"answer":1,"explanation":"小剂量阿司匹林不可逆抑制血小板COX，减少TXA2生成，抑制血小板聚集。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1385","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"阿司匹林最常见的不良反应是？","options":["胃肠道反应（恶心、呕吐、诱发溃疡）","肝肾损害","骨髓抑制","过敏休克"],"answer":0,"explanation":"阿司匹林最常见胃肠道反应，可诱发或加重胃溃疡，宜餐后服用。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1386","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"对乙酰氨基酚与阿司匹林比较，其特点是？","options":["更易引起胃溃疡","抗炎作用更强","几乎无抗炎抗风湿作用","抑制血小板聚集更强"],"answer":2,"explanation":"对乙酰氨基酚解热镇痛作用强而抗炎作用极弱，胃肠反应较轻。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1387","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"强心苷治疗心力衰竭的作用机制是？","options":["抑制心肌细胞钙内流","扩张血管减轻心脏负荷","阻断β受体","抑制心肌细胞膜Na+-K+-ATP酶，增强心肌收缩力"],"answer":3,"explanation":"强心苷抑制Na+-K+-ATP酶，使细胞内Na+增多、Na+-Ca2+交换减少、胞内Ca2+增多，心肌收缩力增强。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1388","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"强心苷最常见的心脏毒性反应是？","options":["室性早搏","房室传导阻滞","窦性心动过缓","心房颤动"],"answer":0,"explanation":"强心苷中毒最常见室性早搏（室性期前收缩），也可出现各类心律失常。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1389","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"地高辛中毒的常见诱发因素是？","options":["低血钙","高血钾","高血钙","低血钾"],"answer":3,"explanation":"低钾血症时心肌对强心苷敏感性增高，易诱发中毒，故用强心苷期间注意补钾。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1390","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"强心苷中毒的解救措施不包括？","options":["立即静脉注射钙剂","用苯妥英钠抗心律失常","用阿托品治疗房室传导阻滞","停药并补钾"],"answer":3,"explanation":"强心苷中毒时禁用钙剂（钙与强心苷协同加重毒性），其余为正确处理措施。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1391","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"硝酸甘油抗心绞痛的主要机制是？","options":["扩张血管，降低心肌耗氧并增加缺血区供血","增强心肌收缩力","减慢心率","抗血小板聚集"],"answer":0,"explanation":"硝酸甘油扩张静脉减少前负荷、扩张冠状动脉增加缺血区供血，降低心肌耗氧。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1392","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"硝酸甘油常用的给药途径是？","options":["口服","舌下含服","肌内注射","静脉推注"],"answer":1,"explanation":"硝酸甘油口服首过消除明显，舌下含服吸收快，是终止心绞痛发作的常用途径。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1393","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"普萘洛尔不宜用于下列哪种心绞痛？","options":["梗死后心绞痛","稳定型心绞痛","劳力型心绞痛","变异型心绞痛"],"answer":3,"explanation":"变异型心绞痛由冠脉痉挛引起，普萘洛尔阻断β受体使α受体占优势，可加重痉挛。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1394","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"钙通道阻滞药（硝苯地平）抗心绞痛的机制不包括？","options":["扩张冠状动脉","扩张外周血管降低心脏负荷","松弛支气管平滑肌","减弱心肌收缩力"],"answer":0,"explanation":"硝苯地平通过扩冠、降负荷、抑制心肌收缩力抗心绞痛，不松弛支气管平滑肌。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1395","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"血管紧张素转换酶抑制剂（卡托普利）降压的特点不包括？","options":["降压同时不加快心率","长期用药不引起水钠潴留","可逆转心肌肥厚","明显升高血糖"],"answer":0,"explanation":"卡托普利降压平稳、可逆转心室重构，不会升高血糖；部分患者可致高血钾。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1396","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"卡托普利最常见的不良反应是？","options":["高血糖","心动过速","支气管痉挛","刺激性干咳"],"answer":3,"explanation":"ACEI抑制缓激肽降解，缓激肽增多刺激呼吸道引起刺激性干咳，为最常见不良反应。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1397","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"氢氯噻嗪的降压机制是？","options":["抑制血管紧张素转换酶","直接扩张小动脉","阻断α受体","早期排钠利尿减少血容量，长期用药降低血管平滑肌细胞内Na+和Ca2+"],"answer":3,"explanation":"噻嗪类利尿药早期通过排钠利尿减少血容量，长期用药使血管平滑肌细胞内钙减少而降压。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1398","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"噻嗪类利尿药长期应用最易引起？","options":["水中毒","高钾血症","低血糖","低钾血症"],"answer":3,"explanation":"氢氯噻嗪排钾利尿，长期应用易致低钾血症，需注意补钾。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1399","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"硝普钠主要用于？","options":["变异型心绞痛的预防","轻度高血压","慢性心衰的长期口服治疗","高血压急症"],"answer":3,"explanation":"硝普钠起效快、作用强，静滴用于高血压急症和急性心衰。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1400","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"利多卡因主要用于治疗？","options":["室上性心动过速","室性心律失常","心房颤动","窦性心动过缓"],"answer":1,"explanation":"利多卡因是室性心律失常（尤其急性心梗并发的室性早搏、室速）的首选药。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1401","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胺碘酮的主要不良反应不包括？","options":["肺纤维化","甲状腺功能紊乱","角膜色素沉着","血糖升高"],"answer":0,"explanation":"胺碘酮可致肺纤维化、甲亢或甲减、角膜色素沉着等，不影响血糖。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1402","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"治疗阵发性室上性心动过速急性发作首选？","options":["阿托品静注","利多卡因静注","胺碘酮口服","腺苷或维拉帕米静注"],"answer":3,"explanation":"腺苷（或维拉帕米）静注是终止阵发性室上速急性发作的首选。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1403","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"阿托品用于治疗下列哪种心律失常？","options":["心房颤动","室性心动过速","窦性心动过缓","室性早搏"],"answer":2,"explanation":"阿托品解除迷走神经对心脏的抑制，用于窦性心动过缓。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1404","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肝素的抗凝机制是？","options":["促进纤维蛋白溶解","直接灭活凝血因子","抑制维生素K环氧化物还原酶","增强抗凝血酶Ⅲ的活性"],"answer":3,"explanation":"肝素与抗凝血酶Ⅲ结合，增强其灭活凝血因子Ⅱa、Ⅹa等的作用。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1405","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肝素过量引起出血的解救药是？","options":["氨甲苯酸","维生素K","鱼精蛋白","酚磺乙胺"],"answer":2,"explanation":"鱼精蛋白为强碱性，与酸性肝素形成复合物使其失活，是肝素过量出血的特效解救药。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1406","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"华法林的抗凝机制是？","options":["促进血小板解聚","增强抗凝血酶Ⅲ","直接抑制凝血酶","拮抗维生素K，抑制凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ合成"],"answer":3,"explanation":"华法林抑制维生素K依赖性凝血因子合成，起效慢，用于需长期抗凝者。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1407","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"华法林过量出血的解救药是？","options":["钙剂","鱼精蛋白","氨甲环酸","维生素K"],"answer":3,"explanation":"维生素K促进凝血因子合成，是华法林过量出血的解救药。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1408","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"链激酶的作用是？","options":["抗血小板聚集","直接溶解纤维蛋白","抑制凝血酶","激活纤溶酶原转变为纤溶酶，溶解血栓"],"answer":3,"explanation":"链激酶激活纤溶系统，用于急性血栓栓塞性疾病（如心梗溶栓）。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1409","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"维生素K用于治疗？","options":["血友病甲","肝素过量出血","链激酶过量出血","华法林过量出血"],"answer":3,"explanation":"维生素K参与凝血因子合成，用于华法林过量及维生素K缺乏性出血。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1410","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"铁剂治疗缺铁性贫血的注意事项不包括？","options":["避免与牛奶同服","与维生素C同服促进吸收","避免与茶同服","与抗酸药同服促进吸收"],"answer":1,"explanation":"抗酸药减少铁的吸收，应避免同服；维C促进铁吸收，牛奶、茶妨碍吸收。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1411","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"口服铁剂最常见的胃肠道不良反应是？","options":["腹泻伴脱水","恶心、呕吐、上腹不适","便秘伴肠梗阻","剧烈腹痛"],"answer":1,"explanation":"口服铁剂常见恶心、呕吐、上腹不适等胃肠道刺激症状，宜餐后服。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1412","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"叶酸和维生素B12用于治疗？","options":["溶血性贫血","缺铁性贫血","再生障碍性贫血","巨幼细胞贫血"],"answer":3,"explanation":"叶酸和B12缺乏引起DNA合成障碍，导致巨幼细胞贫血。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1413","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"奥美拉唑治疗消化性溃疡的机制是？","options":["杀灭幽门螺杆菌","中和胃酸","保护胃黏膜","抑制胃壁细胞质子泵，减少胃酸分泌"],"answer":3,"explanation":"奥美拉唑为质子泵抑制剂，抑制胃酸分泌的最后环节，抑酸作用强而持久。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1414","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"抗幽门螺杆菌治疗常采用？","options":["单用铋剂","单用一种抗生素","质子泵抑制剂+两种抗生素的三联疗法","单用抗酸药"],"answer":2,"explanation":"根除幽门螺杆菌需联合用药，常用PPI+阿莫西林+克拉霉素等三联或四联方案。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1415","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"硫糖铝的作用是？","options":["在胃黏膜表面形成保护膜","中和胃酸","抑制胃酸分泌","促进胃排空"],"answer":0,"explanation":"硫糖铝在酸性环境中聚合成保护膜，覆盖溃疡面促进愈合。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1416","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"异丙嗪属于？","options":["质子泵抑制剂","H2受体阻断药","H1受体阻断药","M受体阻断药"],"answer":2,"explanation":"异丙嗪为第一代H1受体阻断药，用于过敏性疾病，有中枢镇静作用。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1417","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"糖皮质激素的药理作用不包括？","options":["抗休克","抗过敏","抗炎","升高血糖为治疗目的"],"answer":2,"explanation":"糖皮质激素有抗炎、抗过敏、抗休克、免疫抑制等作用，升高血糖是其代谢不良反应而非治疗目的。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1418","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"糖皮质激素隔日疗法的目的是？","options":["增强抗炎效果","减少对肾上腺皮质功能的抑制","延长作用时间","减少胃肠道反应"],"answer":1,"explanation":"隔日晨间给药符合皮质激素分泌节律，减轻对垂体-肾上腺轴的抑制。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1419","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"长期应用糖皮质激素突然停药可引起？","options":["反跳现象与肾上腺皮质功能不全","戒断性抽搐","永久性高血压","甲状腺危象"],"answer":0,"explanation":"突然停药致病情反跳和肾上腺皮质功能不全，应逐渐减量停药。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1420","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"糖皮质激素诱发或加重感染的原因是？","options":["直接损伤黏膜","促进细菌繁殖","抑制免疫功能","升高体温"],"answer":2,"explanation":"糖皮质激素抑制免疫炎症反应，降低机体防御能力，可诱发或加重感染。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1421","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胰岛素最严重的不良反应是？","options":["注射部位脂肪萎缩","过敏反应","胰岛素抵抗","低血糖反应"],"answer":3,"explanation":"胰岛素过量引起低血糖，严重者可致昏迷，是最常见也最严重的不良反应。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1422","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"磺酰脲类降糖药的主要作用机制是？","options":["促进葡萄糖利用","刺激胰岛β细胞释放胰岛素","抑制葡萄糖吸收","增强胰岛素敏感性"],"answer":1,"explanation":"磺酰脲类（格列本脲等）通过刺激残存胰岛β细胞分泌胰岛素降血糖。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1423","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"二甲双胍的主要作用机制是？","options":["补充胰岛素","刺激胰岛素分泌","增强外周组织对胰岛素的敏感性、减少糖异生","抑制胰高血糖素分泌"],"answer":2,"explanation":"二甲双胍不刺激胰岛素分泌，通过增敏、减少肝糖输出等降糖，单用不易致低血糖。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1424","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"双胍类降糖药最严重的不良反应是？","options":["乳酸酸中毒","低血糖","过敏反应","肝功能损害"],"answer":0,"explanation":"二甲双胍严重不良反应为乳酸酸中毒（多见于肾功能不全者），常见反应为胃肠道反应。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1425","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"异烟肼最常见的不良反应是？","options":["周围神经炎","耳毒性","肾毒性","骨髓抑制"],"answer":0,"explanation":"异烟肼可致周围神经炎（与维生素B6缺乏有关），长期用药宜加服维生素B6。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1426","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"利福平的抗结核特点是？","options":["仅抑菌","单用不易耐药","抑菌兼杀菌，易产生耐药性宜联合用药","只对细胞外结核菌有效"],"answer":2,"explanation":"利福平抗菌谱广，对结核杆菌有强大杀菌作用，单用易耐药，必须联合用药。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1427","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"抗结核病药联合用药的主要目的是？","options":["缩短疗程至一周","减少给药次数","降低药物价格","延缓耐药性产生、增强疗效"],"answer":3,"explanation":"联合用药可增强疗效、延缓耐药性产生，是结核病化疗的基本原则。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1428","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"乙胺丁醇的特征性不良反应是？","options":["肾毒性","周围神经炎","耳毒性","球后视神经炎"],"answer":3,"explanation":"乙胺丁醇长期大量应用可致球后视神经炎，表现为视力下降、红绿色盲。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1429","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"甲硝唑对下列哪类感染无效？","options":["真菌感染","厌氧菌感染","阴道滴虫","阿米巴原虫"],"answer":0,"explanation":"甲硝唑对厌氧菌、滴虫、阿米巴有效，对真菌无效。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1430","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"喹诺酮类（左氧氟沙星）不宜用于？","options":["成人呼吸道感染","18岁以下儿童","泌尿道感染成人患者","肠道感染成人患者"],"answer":1,"explanation":"喹诺酮类影响软骨发育，18岁以下儿童、孕妇、哺乳期妇女禁用。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1431","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"头孢菌素类药物的主要不良反应是？","options":["耳毒性","过敏反应","骨髓抑制","周围神经炎"],"answer":1,"explanation":"头孢菌素类可致过敏反应（与青霉素有部分交叉过敏），肾毒性较第一代明显者需注意。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1432","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"氨基糖苷类抗生素最突出的不良反应是？","options":["肝毒性","胃肠道反应","过敏休克","耳毒性和肾毒性"],"answer":3,"explanation":"氨基糖苷类（庆大霉素、链霉素等）主要不良反应为耳毒性（听神经损害）和肾毒性。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1433","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"四环素类不宜用于8岁以下儿童的原因是？","options":["影响牙齿和骨骼发育","引起耳聋","损伤肾小管","抑制骨髓"],"answer":0,"explanation":"四环素类沉积于牙和骨骼，致牙齿黄染（四环素牙）并影响骨骼发育。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1434","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"氯霉素最严重的不良反应是？","options":["抑制骨髓造血功能（再生障碍性贫血）","胃肠道反应","灰婴综合征","过敏反应"],"answer":0,"explanation":"氯霉素可抑制骨髓造血，个别患者发生致死性再生障碍性贫血，是其最严重不良反应。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1435","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"抗恶性肿瘤药共有的主要不良反应是？","options":["耳毒性","骨髓抑制、胃肠道反应、脱发","肾结石","周围神经炎"],"answer":1,"explanation":"抗肿瘤药杀伤增殖细胞，骨髓、消化道黏膜、毛囊等更新快的组织最易受损。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1436","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"环磷酰胺的特征性不良反应是？","options":["肺纤维化","出血性膀胱炎","周围神经炎","牙龈增生"],"answer":1,"explanation":"环磷酰胺代谢物刺激膀胱，可致出血性膀胱炎，用药期间应多饮水。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1437","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"顺铂的主要剂量限制性毒性是？","options":["肾毒性","心脏毒性","肺纤维化","便秘"],"answer":0,"explanation":"顺铂肾毒性明显，用药需水化利尿以保护肾脏。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1438","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"紫杉醇给药前需预防性使用？","options":["糖皮质激素和抗组胺药","抗生素","止血药","利尿药"],"answer":0,"explanation":"紫杉醇可致严重过敏反应（溶媒所致），给药前需用糖皮质激素、抗组胺药预处理。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1439","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"药物在体内发生的化学结构变化称为？","options":["吸收","生物转化（代谢）","分布","排泄"],"answer":1,"explanation":"生物转化指药物在酶作用下发生化学结构变化，多在肝脏进行。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1440","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"药物经肾脏排泄的主要方式是？","options":["肾小球囊内吞","肾小管重吸收","集合管分泌","肾小球滤过和肾小管分泌"],"answer":3,"explanation":"药物及其代谢物主要经肾小球滤过和肾小管分泌排出。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1441","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"碱性药物中毒时，为加速排泄应？","options":["碱化尿液","酸化尿液","大量饮水即可","禁食"],"answer":1,"explanation":"酸化尿液使碱性药物解离增多、重吸收减少，排泄加快。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1442","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"药物主动转运的特点是？","options":["需要载体、耗能、有饱和现象","顺浓度梯度扩散","不耗能","无饱和现象"],"answer":0,"explanation":"主动转运逆浓度梯度、需载体和能量，有饱和与竞争抑制现象。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1443","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"药物被动转运的特点是？","options":["需载体耗能","逆浓度梯度","顺浓度梯度、不耗能","有饱和现象"],"answer":2,"explanation":"被动转运（简单扩散）顺浓度梯度进行，不耗能、无饱和现象。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1444","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"影响药物吸收的因素不包括？","options":["给药途径","血浆蛋白结合率","胃肠道pH","药物溶解度"],"answer":1,"explanation":"血浆蛋白结合率影响分布，不影响吸收。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1445","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"皮下注射比口服吸收快的原因是？","options":["药物极性更小","药物剂量更大","直接进入体循环，避免首过消除","胃肠道pH更适宜"],"answer":2,"explanation":"注射给药绕过胃肠道和肝脏，吸收快而完全。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1446","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"青霉素类的作用机制是？","options":["影响细菌细胞膜通透性","抑制细菌蛋白质合成","抑制细菌核酸合成","抑制细菌细胞壁合成"],"answer":3,"explanation":"青霉素抑制转肽酶，阻碍细菌细胞壁黏肽合成，属繁殖期杀菌剂。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1447","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"青霉素抗菌谱的特点是？","options":["对革兰阴性杆菌作用强","主要对革兰阳性菌有效","对支原体作用强","对真菌有效"],"answer":1,"explanation":"青霉素主要作用于革兰阳性菌及少数革兰阴性菌（如脑膜炎奈瑟菌），对多数革兰阴性杆菌无效。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1448","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"青霉素皮试阳性的处理是？","options":["减量使用","脱敏后使用","禁用青霉素，改用其他药物","加用抗过敏药后使用"],"answer":2,"explanation":"皮试阳性者禁用青霉素，必须更换其他抗菌药物。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1449","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"青霉素最需要警惕的不良反应是？","options":["胃肠道反应","过敏性休克","耳毒性","肾毒性"],"answer":1,"explanation":"过敏性休克发生急骤、可致死，用药前必须询问过敏史并做皮试，药液现配现用。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1450","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"头孢曲松属于第几代头孢菌素？","options":["第一代","第三代","第二代","第四代"],"answer":1,"explanation":"头孢曲松为第三代头孢菌素，对革兰阴性菌作用强，可透过血脑屏障。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1451","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"第一代头孢菌素的特点是？","options":["抗厌氧菌作用强","对革兰阴性菌作用最强","无肾毒性","主要对革兰阳性菌作用强、有一定肾毒性"],"answer":3,"explanation":"第一代头孢（头孢唑林等）抗革兰阳性菌作用强，肾毒性较明显。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1452","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"红霉素属于？","options":["β-内酰胺类","大环内酯类抗生素","氨基糖苷类","四环素类"],"answer":1,"explanation":"红霉素为大环内酯类，主要作用于革兰阳性菌及支原体、衣原体。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1453","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"大环内酯类的主要不良反应是？","options":["耳毒性","胃肠道反应","骨髓抑制","出血"],"answer":1,"explanation":"红霉素类常见恶心、呕吐、腹痛等胃肠道反应，静滴可致血栓性静脉炎。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1454","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"庆大霉素的主要给药途径是？","options":["皮下注射","口服","肌内注射或静脉滴注","雾化吸入"],"answer":2,"explanation":"庆大霉素口服几乎不吸收（仅用于肠道感染），全身感染需注射给药。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1455","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"链霉素对下列哪种感染是首选？","options":["肺炎链球菌肺炎","鼠疫和兔热病","伤寒","梅毒"],"answer":1,"explanation":"链霉素是鼠疫和兔热病（土拉菌病）的首选药，也用于结核病联合化疗。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1456","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"多西环素属于？","options":["磺胺类","大环内酯类","喹诺酮类","四环素类"],"answer":3,"explanation":"多西环素为半合成四环素类，抗菌作用强于四环素，肾功能不全者可选用。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1457","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"磺胺类药物的作用机制是？","options":["抑制细菌DNA回旋酶","抑制细菌二氢叶酸合成酶","抑制细胞壁合成","抑制蛋白质合成"],"answer":1,"explanation":"磺胺类为叶酸代谢抑制剂（抑菌剂），与PABA结构相似而竞争二氢叶酸合成酶。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1458","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"服用磺胺类药物时需碱化尿液的原因是？","options":["防止磺胺结晶析出损伤肾脏","增强抗菌活性","促进药物吸收","减少胃肠道反应"],"answer":0,"explanation":"磺胺药及其乙酰化物在酸性尿中易结晶，碱化尿液可防止肾损害。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1459","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"喹诺酮类的作用机制是？","options":["抑制细菌DNA回旋酶","抑制二氢叶酸合成酶","抑制细胞壁合成","抑制蛋白质合成"],"answer":0,"explanation":"喹诺酮类抑制DNA回旋酶（拓扑异构酶Ⅱ），阻碍DNA复制，为杀菌剂。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1460","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"环丙沙星对下列哪种病原体作用较弱？","options":["流感嗜血杆菌","铜绿假单胞菌","大肠埃希菌","厌氧菌"],"answer":3,"explanation":"多数喹诺酮类对厌氧菌作用弱，主要抗革兰阴性菌及部分阳性菌。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1461","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"异烟肼抗结核的作用特点是？","options":["不能透过血脑屏障","仅抑菌","杀菌作用强、穿透力强、可进入脑脊液","毒性极小无需监测"],"answer":2,"explanation":"异烟肼对结核杆菌杀菌作用强，穿透力强，是各型结核病的基础用药。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1462","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"吡嗪酰胺的主要不良反应是？","options":["周围神经炎","耳毒性","肝损害和高尿酸血症","出血"],"answer":2,"explanation":"吡嗪酰胺可致肝损害和血尿酸升高（诱发痛风），肝功能不全者慎用。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1463","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"乙胺丁醇用药期间需定期检查？","options":["听力","视力和视野","肾功能","血常规"],"answer":1,"explanation":"乙胺丁醇可致球后视神经炎，用药期间定期检查视力、视野和色觉。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1464","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"抗结核化疗的原则是？","options":["症状消失即停药","大剂量冲击","单药长程","早期、联合、适量、规律、全程"],"answer":3,"explanation":"结核病化疗必须遵循早期、联合、适量、规律、全程十字原则。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1465","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"伯氨喹的主要作用是？","options":["预防疟疾感染","杀灭红内期裂殖体，控制症状","杀灭疟原虫红外期和配子体，控制复发与传播","杀灭疟原虫子孢子"],"answer":2,"explanation":"伯氨喹杀灭肝内休眠子和配子体，用于根治间日疟和阻断传播；氯喹控制发作。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1466","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"氯喹的主要作用是？","options":["杀灭休眠子","根治疟疾","防止传播","杀灭红内期疟原虫，迅速控制疟疾发作"],"answer":3,"explanation":"氯喹杀灭红内期裂殖体，是控制疟疾症状发作的首选药。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1467","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"阿苯达唑的主要用途是？","options":["驱肠道线虫（蛔虫、钩虫、蛲虫等）","抗疟","抗真菌","抗结核"],"answer":0,"explanation":"阿苯达唑为广谱驱虫药，对蛔虫、钩虫、蛲虫、绦虫等有效。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1468","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"氨茶碱平喘的机制是？","options":["激动β2受体","抑制磷酸二酯酶，升高细胞内cAMP","阻断M受体","抑制组胺释放"],"answer":1,"explanation":"氨茶碱抑制磷酸二酯酶使cAMP增多，舒张支气管平滑肌，兼有强心利尿作用。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1469","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"氨茶碱静滴过快的主要危险是？","options":["肝损害","低血压","便秘","心律失常、惊厥"],"answer":3,"explanation":"氨茶碱安全范围窄，静滴过快可致心律失常、惊厥甚至死亡，需缓慢滴注。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1470","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"沙丁胺醇平喘的机制是？","options":["选择性激动支气管β2受体","阻断M受体","抑制磷酸二酯酶","阻断组胺受体"],"answer":0,"explanation":"沙丁胺醇为选择性β2受体激动剂，舒张支气管平滑肌，心血管不良反应较轻。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1471","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"色甘酸钠的作用是？","options":["稳定肥大细胞膜，预防哮喘发作","舒张支气管平滑肌","抗炎抗过敏","稀释痰液"],"answer":0,"explanation":"色甘酸钠抑制肥大细胞脱颗粒，主要用于预防哮喘发作，对发作期无效。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1472","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"镇咳药可待因的作用特点是？","options":["稀释痰液","外周性镇咳","中枢性镇咳作用强，有成瘾性","扩张支气管"],"answer":2,"explanation":"可待因直接抑制延髓咳嗽中枢，镇咳作用强，反复应用可成瘾，严格控制使用。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1473","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"氯化铵属于？","options":["中枢性镇咳药","恶心性祛痰药","外周性镇咳药","平喘药"],"answer":1,"explanation":"氯化铵刺激胃黏膜引起恶心，反射性促进支气管腺体分泌，稀释痰液。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1474","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"缩宫素用于？","options":["抑制宫缩","保胎","治疗痛经","产后止血和引产"],"answer":3,"explanation":"缩宫素兴奋子宫平滑肌，小剂量用于催产引产，大剂量用于产后止血。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1475","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"麦角新碱用于？","options":["催产","产后子宫出血（促进子宫强直性收缩）","引产","保胎"],"answer":1,"explanation":"麦角新碱使子宫持续强直收缩，只用于产后止血，禁用于催产引产。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1476","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"缩宫素用于催产时的注意事项不包括？","options":["有头盆不称者禁用","密切观察宫缩与胎心","严格掌握剂量避免子宫强直收缩","大剂量快速静滴以缩短产程"],"answer":2,"explanation":"催产时小剂量缓慢滴注并严密监护；大剂量快速滴注可致子宫破裂、胎儿窘迫。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1477","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"维生素D用于防治？","options":["脚气病","坏血病","佝偻病和骨软化症","夜盲症"],"answer":2,"explanation":"维生素D促进钙磷吸收与骨盐沉积，用于防治佝偻病、骨软化症。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1478","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"维生素C用于防治？","options":["脚气病","佝偻病","夜盲症","坏血病"],"answer":3,"explanation":"维生素C缺乏引起坏血病（毛细血管脆性增加、出血）。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1479","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"维生素A用于防治？","options":["夜盲症","坏血病","佝偻病","脚气病"],"answer":0,"explanation":"维生素A参与视紫红质合成，缺乏致夜盲症、干眼病。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1480","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"维生素B1用于防治？","options":["佝偻病","坏血病","脚气病","夜盲症"],"answer":2,"explanation":"维生素B1缺乏引起脚气病（周围神经炎、心功能不全等）。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-1481","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"右旋糖酐的主要作用是？","options":["扩充血容量（低分子右旋糖酐兼有抗凝作用）","补充营养","纠正酸中毒","利尿"],"answer":0,"explanation":"右旋糖酐提高血浆胶体渗透压扩充血容量，低分子者还抑制红细胞和血小板聚集。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1482","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"西地那非类药物治疗勃起功能障碍的禁忌是？","options":["高血压患者","正在服用硝酸酯类药物者","糖尿病患者","老年人"],"answer":1,"explanation":"硝酸酯类与该药合用可致严重低血压，绝对禁忌。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1483","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"缩宫素引产时最严重的并发症是？","options":["子宫破裂","产后出血","感染","羊水过少"],"answer":0,"explanation":"缩宫素过量致子宫强直性收缩，可发生子宫破裂、胎儿窘迫。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1484","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"硫酸镁用于妊娠高血压的主要作用机制是？","options":["抑制醛固酮","利尿降压","镁离子拮抗钙离子，解除血管痉挛","阻断α受体"],"answer":2,"explanation":"硫酸镁中镁离子拮抗钙离子，松弛血管平滑肌，是子痫前期解痉首选。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1485","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"硫酸镁中毒的解救药是？","options":["葡萄糖酸钙","氯化钾","碳酸氢钠","维生素K"],"answer":0,"explanation":"镁离子中毒用钙剂（葡萄糖酸钙）拮抗解救。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1486","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"缩宫素的禁忌证不包括？","options":["前置胎盘","胎位异常","头盆不称","产后子宫收缩乏力出血"],"answer":2,"explanation":"产后宫缩乏力出血是缩宫素的适应证；头盆不称、胎位异常、前置胎盘等为禁忌。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1487","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"治疗子痫首选的解痉药物是？","options":["肼屈嗪","地西泮","硝苯地平","硫酸镁"],"answer":3,"explanation":"硫酸镁是子痫前期-子痫解痉治疗的首选药物。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1488","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"催产素引产失败最常见的原因是？","options":["羊水过多","胎儿过大","宫颈不成熟","产妇年龄大"],"answer":2,"explanation":"宫颈Bishop评分低（宫颈不成熟）是引产失败最常见原因。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1489","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"麦角新碱禁用于催产的原因是？","options":["引起子宫强直性收缩致胎儿窘迫、子宫破裂","作用太弱","半衰期太长","过敏率高"],"answer":0,"explanation":"麦角新碱引起子宫持续强直收缩，产程中使用可致子宫破裂和胎儿缺氧。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1490","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"维生素K3的给药途径是？","options":["动脉注射","静脉推注","皮下注射","肌内注射（口服需用缓释剂型）"],"answer":3,"explanation":"维生素K3、K4为人工合成水溶性制剂，刺激性大，需肌注或口服缓释剂型，静注过快可致血压骤降。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1491","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"垂体后叶素用于肺咯血的作用机制是？","options":["抑制纤溶酶原激活","促进凝血因子合成","抗纤维蛋白溶解","收缩肺小动脉，减少出血"],"answer":3,"explanation":"垂体后叶素含加压素，收缩肺小动脉和毛细血管，用于大咯血急救。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1492","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"垂体后叶素的禁忌证不包括？","options":["妊娠","高血压","冠心病","支气管扩张咯血"],"answer":2,"explanation":"垂体后叶素收缩冠脉和升高血压，冠心病、高血压、妊娠者禁用；支气管扩张咯血是其适应证。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1493","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"氨甲苯酸的作用机制是？","options":["抗血小板聚集","促进凝血因子合成","收缩血管","抑制纤维蛋白溶解（抗纤溶药）"],"answer":3,"explanation":"氨甲苯酸抑制纤溶酶原激活，用于纤溶亢进所致出血。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1494","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肝素在体内的抗凝特点不包括？","options":["起效快","口服有效","体内体外均抗凝","主要经肝代谢"],"answer":1,"explanation":"肝素口服不吸收，需注射给药，体内体外均有抗凝作用。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1495","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"枸橼酸钠的抗凝机制是？","options":["络合钙离子，阻止凝血","拮抗维生素K","增强抗凝血酶Ⅲ","抑制血小板聚集"],"answer":0,"explanation":"枸橼酸钠与血中钙离子络合，用于体外抗凝（如血液保存）。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1496","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"华法林抗凝的起效时间是？","options":["立即起效","用药后24-72小时起效","1周后起效","2周后起效"],"answer":1,"explanation":"华法林需待体内原有凝血因子耗竭后才起效，一般24-72小时。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1497","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"低分子肝素与普通肝素比较，其特点是？","options":["出血不良反应较少、不需常规监测APTT","出血更多","半衰期更短","抗凝作用更强"],"answer":0,"explanation":"低分子肝素抑制Ⅹa为主，出血风险较低，使用方便。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1498","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"阿司匹林抗血栓的适宜剂量是？","options":["大剂量（3-5g/日）","小剂量（75-100mg/日）","中剂量（1g/日）","任意剂量"],"answer":1,"explanation":"小剂量阿司匹林选择性抑制血小板TXA2，大剂量反而抑制前列环素合成、减弱抗栓效果。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-1499","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"双嘧达莫的抗栓机制是？","options":["溶解血栓","阻断血小板ADP受体","抑制凝血酶","抑制磷酸二酯酶，升高血小板cAMP"],"answer":3,"explanation":"双嘧达莫抑制磷酸二酯酶和腺苷摄取，使血小板cAMP增多而抑制聚集。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-1500","_shard":"qk-yiliao-02"}]);